INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_emp_ion', 'EMP / Ion', NULL, '{"nature":"objets","mot":"EMP / Ion","regle":"Sur au moins 1 dégât réel à un système exposé, une fonction électronique appropriée est neutralisée jusqu''à la fin de sa prochaine activation. Sans effet sur la magie, l''âme ou une biologie purement organique. *(Version chiffrée de #226, qui précise celle de #1.)*"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_invariant', 'Invariant', NULL, '{"nature":"objets","mot":"Invariant","regle":"Résiste aux corrections ordinaires de l''Hologramme ; ne voit jamais plus que le capteur relié. Il reste piratable et destructible."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_calibre', 'Calibré', NULL, '{"nature":"objets","mot":"Calibré","regle":"Préparé contre une signature connue ; jamais universel. Un mauvais diagnostic ne donne aucun effet."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_surchauffe', 'Surchauffe', NULL, '{"nature":"objets","mot":"Surchauffe","regle":"Après un Tir de suppression ou un usage intensif, l''arme refroidit jusqu''à ta prochaine activation avant tout nouvel usage intensif. *(Version chiffrée d''Helios #150, qui précise « selon profil ».)*"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_verrouille', 'Verrouillé', NULL, '{"nature":"objets","mot":"Verrouillé","regle":"Exige une autorisation biologique, psychique, nanitique ou cryptographique (voir 3.6)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_fiable_automatique_rafale_dispersion_x_smartlink', 'Fiable, Automatique, Rafale, Dispersion X, Smartlink', NULL, '{"nature":"objets","mot":"Fiable, Automatique, Rafale, Dispersion X, Smartlink","regle":"Définis au chapitre Réalité. Fiable : un 1 naturel reste un échec, sans échec narratif ni enrayement dû à l''arme. Automatique : autorise la Suppression."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_souillure_x_corruptif_x_instable', 'Souillure X, Corruptif X, INSTABLE', NULL, '{"nature":"objets","mot":"Souillure X, Corruptif X, INSTABLE","regle":"Voir 3.8."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_biphysique', 'Biphysique', NULL, '{"nature":"objets","mot":"Biphysique","regle":"L''objet ou l''arme peut toucher ou manipuler une manifestation immatérielle accessible (Ombre, entité déphasée, effet intangible), avec son profil normal. Ni détection, ni bonus de DGT, ni Perforant spirituel. | #45, #50, #54, #65, #70, #170, #171"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_laser', 'Laser', NULL, '{"nature":"objets","mot":"Laser","regle":"Arme à énergie dirigée, sans munition conventionnelle. Aucune règle propre. | #87 à #90, #104, #114"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_chaleur', 'chaleur', NULL, '{"nature":"objets","mot":"chaleur","regle":"Saveur Phoenix, sans effet de jeu. Ce n''est **pas** Incendiaire. | #2, #3, #6"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_zone_conique', 'Zone conique', NULL, '{"nature":"objets","mot":"Zone conique","regle":"Attaque de zone en cône, sur la portée indiquée, avec les règles de zone du Moteur. | #112, #151"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_automatique_lourd', 'Automatique lourd', NULL, '{"nature":"objets","mot":"Automatique lourd","regle":"Automatique ; la Suppression peut couvrir une zone ou un axe plus large (texte de #149). | #149"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_auto_alimente', 'Auto-alimenté', NULL, '{"nature":"objets","mot":"Auto-alimenté","regle":"Aucune munition ni cellule à gérer. | #104"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('glossaire', 'objets', 'glossaire_psychique', 'Psychique', NULL, '{"nature":"objets","mot":"Psychique","regle":"L''objet ne fonctionne qu''avec un pouvoir mental du porteur ; il n''en donne aucun. | #105, #106"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'catalogue_5_1', 'Équipement de Chasse (#2 à #41)', NULL, '{"nature":"objets","numero":"5.1","texte":"**Armes de Chasse** (profil de Chasse ; prix et profil de base au catalogue Réalité)\n\n| # | Objet | Profil |\n|---|---|---|\n| 2 | Phoenix PCK-08 « Feather » | DGT 4, Perforant 1, chaleur |\n| 3 | Phoenix BA-037 « Sun Axe » | DGT 7, Perforant 1, chaleur |\n| 4 | Raven CL-038 « Claymore » | DGT 8, EMP |\n| 5 | Raven SP-016 « Raven Spear » | DGT 6, allonge 1,5 m, Perforant 1, EMP |\n| 6 | Phoenix PW-026 « Vampire Killer » | DGT 7, allonge 3,5 m, Perforant 1, chaleur. Le nom est commercial, pas une propriété anti-Vampire. |\n| 7 | Raven MC-025 « Hitman » | DGT 5, allonge 1,5 m, Perforant 2 |\n| 8 | Owl LC-014 « Chasseur » | Arbalète, DGT 7, 25 m, Perforant 1 |\n| 9 | Raven HT-014 « Immobilisateur » | Taser lourd, DGT 6, 15 m |\n\n**Munitions**\n\n| # | Objet | Accès / prix | Effet |\n|---|---|---|---|\n| 10 | Raven Drill | A, 5 pour le prix d''une boîte | Perforant 1 |\n| 11 | Raven Flash | C/A, 20 par boîte | Sur une Altération, Aveuglé jusqu''à la fin de la prochaine activation de la cible, si le mode d''attaque est cohérent |\n| 12 | Raven Volto | A, 10 par boîte | Électrique. Sur 1 dégât réel à une cible biologique : Vigueur + Constitution contre 15, sinon aucune Réaction jusqu''à la fin de sa prochaine activation. EMP contre l''électronique exposée. |\n| 13 | Phoenix Pyro | C/A, 20 par boîte | Incendiaire |\n| 14 | Noyau d''argent | C, prix ×2, 10 munitions | Compte comme Argent, rien de plus |\n| 15 | Fer froid | C/A, prix ×2, 10 munitions | Compte comme Fer froid, rien de plus |\n| 16 | Raven Reliquary | A / GT-01, prix ×2, 5 munitions | DGT −2. Sur 1 dégât réel, la substance portée (liquide, poudre, matière rituelle) est déposée dans la blessure. Aucune autre munition spéciale en même temps. |\n| 17 | Munition angélique | T / A-GT-01, environ prix ×3 pour 6 | Sacré, Angélique. Aucun DGT en plus ; exploite une vraie faiblesse divine, touche certaines manifestations spirituelles, soutient les talents appropriés. |\n\n**Matériel rituel**\n\n| # | Objet | Accès / prix | Effet |\n|---|---|---|---|\n| 18 | Eau bénite | T / A-GT-01, 25 $ l''ampoule | Sacré ; aucun DGT ; support d''une faiblesse ou d''un rite réel |\n| 19 | Sel rituel | C, 20 $/kg ; consacré T / A-GT-01, 60 $/kg | Ne crée aucune barrière seul ; sert aux rites qui l''exigent |\n| 20 | Kit de scellement | A/T, 250 $ | Craies, encres, cires, sels… Aucun pouvoir propre. |\n| 21 | Ofuda vierges | T, 30 $ les 20 | Supports Onmyoji ; le pouvoir vient du talent |\n| 22 | Ancrages Shi | R/T, 300 $ le jeu | Supports du Sceau de Vacuité et du Grand Scellement ; aucun effet seuls |\n| 23 | Kit d''offrandes néopaïen | T, 50 à 500 $ | Le symbole compte plus que le prix |\n\n**Capture et confinement**\n\n| # | Objet | Accès / prix | Effet |\n|---|---|---|---|\n| 24 | Owl Flashglue | C/A, 80 $ | Grenade, zone 3 m. Agilité + Athlétisme contre 15, sinon Entravé. Se libérer : 1 PA et Vigueur + Athlétisme contre 18. Ne bloque aucune fuite surnaturelle. |\n| 25 | Raven Deadlock | A, 250 $ | Entraves : les briser demande Vigueur + Athlétisme contre 21. Ne bloque aucun pouvoir. |\n| 26 | Raven Gravewire | A, 1 200 $ | Filet, 10 m ; une réussite Entrave. Le maillage reçoit un matériau préparé (argent, fer froid, consacré) pour une vulnérabilité réelle au contact prolongé. |\n| 27 | Raven « No Witness » | A, 450 $ | Capuche opaque, insonorisée, isolée des ondes. Bloque les pouvoirs qui passent par le regard, la voix ou une communication que la capuche coupe. |\n| 28 | Raven Black Ark | A / GT, 1 800 $ | Conteneur hermétique blindé contre les ondes ; aucune protection magique |\n| 29 | Raven Null Cage | P / GT, 6 500 $ | Calibrée en 10 min contre un mode de fuite identifié ; une fuite par ce mode doit dépasser 18 (ou la Puissance de l''effet). Batterie 2 h, un mode à la fois. |\n| 38 | Raven « Shut Up & Look Away » | A, 900 $ | Masque : 1 PA pour fermer ou rouvrir les canaux. Bloque un pouvoir qui passe par un canal coupé ; le porteur perd aussi ce sens. |\n| 39 | Raven HSE-11 « Daybreak » | P / GT-11, 5 500 $ | Solaire. Déploiement 2 PA, maintien 1 PA par round, cône de 10 m : une cible qui finit son activation exposée subit un round de soleil direct (une fois par round). Trois rounds d''autonomie. *En observation (passation §31).* |\n| 40 | Raven « Last Door » | P / GT-33, 6 500 $ | Quatre balises calibrées sur une extraction technologique déjà observée ; déploiement 2 PA. Contre une extraction de ce système dans la zone, Esprit + Technologie de l''opérateur contre le système : en réussite, l''extraction échoue. Ni magie ni passage spirituel. |\n\n**Investigation**\n\n| # | Objet | Accès / prix | Effet |\n|---|---|---|---|\n| 30 | Byron « Analyst » | C/A, 1 200 $ | Lunettes IR, relief, surface, détection techno : +3 quand c''est pertinent. Ne perce pas l''Hologramme. |\n| 31 | DIVE DSA-480 | C/A, 3 500 $ | Scanner de scène multispectral : des tests de laboratoire deviennent possibles sur le terrain |\n| 32 | Drones traqueurs SCT12 | C/A, 2 000 $ les 10 | Suivent une forme, un signal ou un traceur environ 4 h. Rien de surnaturel. |\n| 33 | Raven « Mnemosyne » | P / GT-00 ou GT-01, 4 800 $ | Invariant. Un phénomène SR/R filmé n''est plus réécrit ; une cible V reste filmée sous forme humaine. |\n| 41 | Raven « Murder Box » | P/A, 3 500 $ | Quatre microdrones (thermique, radio, chimique, optique) : un test se résout depuis le meilleur point du réseau. Ni bonus cumulé ni attaque. |\n\n**Renvois au catalogue Réalité** : #34 Black Feathers, #35 Black Dog, #36 Gallowglass II légère, #37 Gallowglass II lourde. Ces fiches ne portent aucune valeur de Vérité. Elles sont gardées comme renvois d''une ligne, pour que le Builder retrouve leur identifiant."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'catalogue_5_2', 'Marché de Vérité des Exilés (#44 à #84)', NULL, '{"nature":"objets","numero":"5.2","texte":"**Runes whurtennes**\n\n| # | Objet | Accès / prix | Effet |\n|---|---|---|---|\n| 44 | Plaque de Fer | V1, 1 500 $, charge | 1 PA : pour la scène, l''objet interagit avec une Ombre ou une manifestation immatérielle. Aucun bonus. |\n| 45 | Lame de Fer stabilisée | V2, 8 000 $ + arme, inscription | Biphysique permanent ; restauration par un runiste après un dommage sérieux |\n| 46 | Marteau de Scellement | V2, 12 000 $ | DGT 7. 1 PA hors attaque : une pointe scelle une ouverture pour la scène (difficulté 18 pour ouvrir par force, magie ou immatérialité). |\n| 47 | Brigandine de Garde | V2, 15 000 $ | Armure 2 ; la première source de dégâts surnaturels du scénario est réduite de 3, puis la charge s''éteint |\n| 48 | Verrou Nibelungen | V1, 4 000 $ | Scellement 18 ; le contenant reste destructible |\n| 49 | Plaque de Veille | V1, 1 000 $ | Alerte mentale au porteur de la clé runique si la condition fixée se produit (franchi, déplacé, ouvert, retiré) ; une scène |\n| 50 | Projectile de Fer | 250 $ | Usage unique ; tir Biphysique, sans bonus de DGT |\n| 51 | Tête de Scellement | 600 $ | Projectile qui déploie un Scellement 15 jusqu''à la fin du round suivant |\n| 52 | Ruban de Veille | 300 $ | Alerte la clé runique s''il est coupé ou franchi ; usage unique |\n| 53 | Jeton de Garde | 750 $ | À briser en Réaction : −2 aux dégâts d''une source surnaturelle ; usage unique |\n\n**Technomagie azménorienne et arsenal de Rupture**\n\n| # | Objet | Accès / prix | Effet |\n|---|---|---|---|\n| 54 | Capteur biphysique portatif | V2, 12 000 $ | Détecte magie active, Flux perturbé, immatériel présent, anomalie dimensionnelle ; ni nature ni auteur |\n| 55 | Relais de déclenchement croisé | V2, 18 000 $ | Relie une fonction technique à un phénomène détecté (porte, alarme, enregistreur) ; jamais une attaque |\n| 56 | Convertisseur biphysique de secours | V3, 55 000 $ | Sans technomage : 1/scène, alimente un appareil portatif un round avec une charge magique préstockée. Avec le talent : usage normal. |\n| 57 | Relais discontinu | V2, 15 000 $ | 1 PA : liaison de données à moins de 1 m à travers un mur ; ne contourne aucune sécurité |\n| 58 | Optique de phase | V2, 28 000 $, 1/scène | 1 PA : un round, le capteur voit à travers 1 m de matière non surnaturelle |\n| 59 | Module de trajectoire décalée | V3, 45 000 $ | 1/scène, la sortie du tir est déplacée de 1 m (contourner un angle) ; aucun bonus |\n| 60 | Kit Microbrèche | V4, 120 000 $ | 3 PA, 1/scénario : fenêtre de 20 cm à travers 1 m de matière ; rien de vivant |\n| 61 | Optique de Vérité | V3, 35 000 $, très surveillée | Montre la nature et la morphologie vraies d''une cible V/SR/R, sans la Révéler. Une HDS adaptée peut s''y opposer. |\n| 62 | Enregistreur invariant | V3, 45 000 $ | Invariant ; avec l''Optique de Vérité, garde la morphologie vraie |\n| 63 | Scanner de Signature de Vérité | V3, 55 000 $ | Reconnaît un individu déjà observé à l''Optique, malgré un changement d''apparence ou d''état ; pas de localisation |\n| 64 | Fenêtre de Vérité | V4, 130 000 $ | Installation : les écrans d''une petite pièce montrent la scène vraie. Ne Révèle personne. |\n| 65 | Module d''Interférence | V2, +20 000 $ à une arme | L''arme devient Biphysique |\n| 66 | Ancre d''Ombre | V3, 50 000 $ | Zone de 3 m : se dématérialiser, quitter le plan ou rompre l''ancrage demande Volonté + Force Mentale contre 18, sinon l''action et son coût sont perdus |\n| 67 | Cage de Vérité | V4, 110 000 $ | Même principe que l''Ancre, contre 21 ; la sortie physique reste possible |\n| 68 | Module de Désancrage | V4, +60 000 $ à une arme d''Interférence | 1/scène par cible, après un coup réussi : Volonté + Force Mentale contre 18, sinon plus d''immatérialité ni de changement de support jusqu''à la fin de la scène |\n| 69 | Jadehook | V2, 9 000 $ | Arbalète de poing, DGT 6, 35 m ; rail pour Plaque de Fer ou Tête de Scellement |\n| 70 | Black Nail | V2, 6 500 $ | Couteau DGT 4, Biphysique |\n| 71 | Lanternette biphysique | V1, 7 000 $ | Lampe gobeline : signale une manifestation magique, immatérielle ou dimensionnelle proche |\n| 72 | Coffret du passeur | V2, 14 000 $ | Valise : Scellement 18 pendant une scène, et compartiment invariant |\n\n**Armes, armures et composants**\n\n| # | Objet | Prix | Profil |\n|---|---|---|---|\n| 73 | Épée nibelungen runique-ready | 2 500 $ | DGT 6, logement de plaque, très robuste |\n| 74 | Hache de clan runique-ready | 3 500 $ | DGT 7, logement de plaque |\n| 75 | Armure de clan | 8 000 $ | Armure 4, plaques pour Rune de Garde |\n| 76 | Manteau de Jade | 3 000 $ | Armure 2, poches occultes |\n| 77 | Viseur technomagique neutre | 2 500 $ | Support d''un capteur biphysique ou d''une Optique ; rien sans module |\n| 78 | Batterie de Flux stabilisée | 5 000 $ | Environ une scène d''usage intensif d''un prototype |\n| 79 | Craie de Flux | 50 $ la boîte | Inscriptions et calibrations |\n| 80 | Encre runique whurtenne | 300 $ la dose | Inscriptions durables |\n| 81 | Fil d''ancrage azménorien | 500 $ les 10 m | Conducteur d''Ancres, de Cages et de capteurs |\n| 82 | Cristal de phase | 1 000 $ | Réparation des modules Fracture ; fragile, traçable |\n| 83 | Clé invariante | 750 $ | Stockage d''un Enregistreur invariant |\n| 84 | Matrice de rune vide | 250 $ | Plaque rechargeable par un runiste |"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'catalogue_5_3', 'Marché xéno (#87 à #130)', NULL, '{"nature":"objets","numero":"5.3","texte":"**Armes à énergie et à projectiles**\n\n| # | Objet | Accès / prix | Profil |\n|---|---|---|---|\n| 87 | Pistolet laser | M1, 2 000 Dykal | DGT 5, 25 m, Laser, 100 tirs |\n| 88 | Pistolet laser lourd | M1, 5 000 | DGT 6, 25 m, Laser, 75 tirs |\n| 89 | Fusil laser | M1, 15 000 | DGT 7, 80 m, Laser, 1 000 tirs |\n| 90 | Fusil laser de précision | M2, 150 000 | DGT 8, 250 m, Laser, optique, 50 tirs |\n| 91 | Pistolet à ions | M1, 2 000 | DGT 4, 20 m, EMP, 75 tirs |\n| 92 | Fusil à ions | M2, 10 000 | DGT 6, 60 m, EMP, 25 tirs |\n| 93 | Pistolet à plasma | M2, 10 000 | DGT 7, 25 m, Incendiaire, Surchauffe, 50 tirs |\n| 94 | Fusil à plasma | M2, 35 000 | DGT 9, 70 m, Incendiaire, Perforant 1, Surchauffe, 100 tirs |\n| 95 | Sniper plasma | M3, 200 000 | DGT 9, 200 m, Incendiaire, Perforant 2, Surchauffe, 50 tirs |\n| 96 | Grenade plasma | M2, 2 000 | DGT 10, lancer, Zone 4 m, Incendiaire |\n| 97 | Fusil projectile galactique | M1, 2 000 | DGT 7, 90 m, Fiable, Perforant 1, 10 |\n| 98 | Sniper projectile galactique | M2, 50 000 | DGT 9, 250 m, Perforant 1, 10 |\n| 99 | Blaster Atomus (Thalsios) | M2, 45 000 | Rafale : DGT 7, 70 m, Suppression. Concentré : DGT 9, 90 m, Perforant 1, tir unique. Changement gratuit, une fois par activation. |\n| 100 | Module Hydro-Atomus | M2, 12 000 | Une arme Atomus ou laser marche sous l''eau, à demi-portée sauf modèle Hydroguard |\n| 101 | Karpan Trius | M1, 7 500 | DGT 5, 25 m, projectile, blindé, furtif |\n| 102 | Vultar Trius | M2, 50 000 | DGT 5, 50 m, EMP, Automatique, forte réserve |\n| 103 | Lantarksan Trius | M2, 75 000 | DGT 7, 70 m, EMP, étanche, blindé |\n| 104 | GO-02 (reliquat rocréen) | M3, 1 500 000 | DGT 6, 60 m, Laser, EMP, Auto-alimenté. Pièce rare et politiquement sensible. |\n| 107 | Pistolet plasma Sérys | 15 000 | DGT 7, 30 m, Incendiaire, Surchauffe |\n| 108 | Fusil plasma Sérys | 50 000 | DGT 9, 90 m, Incendiaire, Perforant 1, Surchauffe |\n| 109 | Répétiteur Sérys | 90 000 | DGT 8, 70 m, Incendiaire, Automatique, Surchauffe |\n| 110 | Sniper Sérys | 180 000 | DGT 10, 250 m, Incendiaire, Perforant 2, optique thermique |\n| 111 | Mitrailleuse Sérys | 250 000 | DGT 10, 80 m, Incendiaire, Perforant 1, Automatique, Surchauffe |\n| 112 | Lance-plasma Sérys | 120 000 | DGT 9, 20 m, Zone conique, Incendiaire, Surchauffe |\n| 113 | Lance-roquette Sérys | 300 000 | DGT 12, 120 m, Zone 5 m, Incendiaire, Perforant 2 |\n| 114 | Sellecion 12 (Ad''rak) | M3, 80 000 | DGT 10, 140 m, Laser, Perforant 1 ; −3 sous pression sans adaptation ni Vigueur 4+ ; encombrant |\n| 115 | TK X (Xewen) | M3, 50 000 | DGT 8, 70 m, EMP ; sur échec narratif, se désassemble (2 PA pour la remettre) |\n| 116 | Tanax Alpha (ménomah) | M3, 75 000 | Cinétique : DGT 7, 60 m. Perturbation : DGT 5, EMP, Altération possible des capteurs ou de la mobilité d''un drone. Environ 50 h. |\n| 117 | Pistolet AIDH 2e génération | M3, 45 000 équivalent | DGT 7, 35 m, Perforant 1, 200 tirs, Verrouillé ; cartouche-source spécialisée |\n| 118 | Fusil AIDH 1re génération | M3, 200 000 équivalent | Automatique : DGT 8, 80 m. Perforant : DGT 10, 70 m, Perforant 2, tir unique. Verrouillé. |\n\n**Armes psychiques et objets d''exception**\n\n| # | Objet | Accès | Effet |\n|---|---|---|---|\n| 105 | Résonateur Feeshri de volonté | M3/M4, prix variable, Psychique, Verrouillé | Un pouvoir mental à courte portée du porteur porte jusqu''à 50 m si la cible reste dans le viseur. Même PA, même jet, même Défense occulte. N''accorde aucun pouvoir. |\n| 106 | Carabine Feeshri « Nœud bleu » | M4, mission ou dette majeure | Avec un pouvoir de domination ou d''intrusion, 1/scène, deux cibles proches pour une activation ; chacune se défend |\n| 119 | Pastille d''armement AIDH 1re génération | M4, 2 000 000 Dykal minimum, X | Matérialise jusqu''à trois configurations d''armes réelles (1 PA pour changer), chacune avec son profil. Sur un échec narratif lié à elle, se verrouille jusqu''à réparation. Objet de scénario, de vol ou de dette ; jamais une dotation AIDH moderne. |\n\n**Lames**\n\n| # | Objet | Accès / prix | Profil |\n|---|---|---|---|\n| 120 | Couteau de survie vibrant | M0/M1, 350 | DGT 4, Perforant 1, outil |\n| 121 | Dague mono-filament | M2, 2 000 | DGT 5, Perforant 3, rétractable |\n| 122 | Spectrale S40 | M2, 1 000 | DGT 6, lame vibrante, occulteur visuel |\n| 123 | Hache mono-filament | M2, 5 000 | DGT 7, Perforant 3 |\n| 124 | LC-108X | M2, 2 500 | DGT 7, EMP, champ court |\n\n**Modules et consommables**\n\n| # | Objet | Accès / prix | Effet |\n|---|---|---|---|\n| 125 | Cellule universelle Shaediri | M1, 3 000 | Recharge un appareil M1/M2 sur le réseau terrestre en environ 1 h |\n| 126 | Kit d''ergonomie xéno | M1, 1 500 à 10 000 | Supprime le −3 d''ergonomie après adaptation réussie |\n| 127 | Brouilleur de télémétrie | M2, 8 000 | Une scène : bloque les émissions automatiques d''un appareil connu |\n| 128 | Étui de quarantaine énergétique | M1, 4 000 | Masque les émissions d''une cellule, d''un module ou d''un échantillon |\n| 129 | Balise de rappel cislunaire | M2, 2 PdC | Marque une cargaison pour une filière d''extraction ; ne téléporte rien |\n| 130 | Cartouche de matière AIDH ancienne | M3, 5 000 à 20 000 | Recharge d''un générateur de 1re ou 2e génération |"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'catalogue_5_4', 'AIDH moderne (#133 à #175, #230, #231)', NULL, '{"nature":"objets","numero":"5.4","texte":"Tout le matériel est **Verrouillé** par défaut, et l''échelle est volontairement au-dessus des armes terrestres.\n\n**Générique**\n\n| # | Objet | Niveau | Fonction |\n|---|---|---|---|\n| 133 | Cipherline C-9 | D | Communicateur crypté en maillage ; clés révocables ; pas d''interstellaire sans relais |\n| 134 | Omnispectre OS-6 | D | Scanner multispectral ; des mesures, pas l''expertise |\n| 135 | Handshake IU-4 | D | Pont d''interface vers des normes connues ; ne pirate rien |\n| 136 | Mantis Field Tool | D | Multitool de microfabrication et de réparation de terrain |\n| 137 | Wisp R-3 | D/O | Microdrone de reconnaissance, 4 h ; pas de PA propres |\n| 138 | Nightjar EW-5 | O | Brouilleur sélectif, contre-brouillage, réseau fermé ; rien sur la télépathie, la magie ou l''Hologramme |\n| 139 | Lattice Cell LC-12 | D/O | Cellule standard AIDH |\n| 140 | Homecall BR-7 | D/O | Balise de récupération ; appelle une équipe, ne téléporte pas |\n| 141 | Aegis Medpack M-8 | D/O | Stabilisation nanitique ; aucun soin gratuit |\n| 142 | Farwalker ES-4 | O | Combinaison environnementale, Armure 2, étanche |\n| 143 | Ghostbox D-10 | D/O | Noyau de données isolable, journal d''accès ; **pas** invariant |\n| 144 | Forgelet F-2 | O | Fabricateur de terrain ; ni matière exotique ni Calamitechnologie |\n\n**Armes**\n\n| # | Objet | Niveau | Profil |\n|---|---|---|---|\n| 145 | Defensor | D | DGT 14, 50 m, Perforant 2, semi-automatique, ~1 000 tirs. Ignore le premier enrayement mécanique du scénario. *En observation (§31).* |\n| 146 | Praetor C-14 | O | DGT 14, 70 m, Automatique, Perforant 1, ~1 500 tirs ; repliable (1 PA) |\n| 147 | Custodian AR-9 | O | Standard : DGT 16, 100 m, Automatique, Perforant 2. Perforant : DGT 17, 90 m, Perforant 3, tir unique. 1 PA pour changer. |\n| 148 | Long Watch SR-6 | L | DGT 18, 400 m, Perforant 3, 100 tirs ; subsonique DGT 16, 250 m. *En observation (§31).* |\n| 149 | Cerberus HMG-3 | L | DGT 17, 120 m, Automatique lourd, Perforant 2, ~10 000 tirs ; demande servomotricité ou affût |\n| 150 | Helios PR-8 | L | DGT 18, 100 m, Incendiaire, Perforant 2, Surchauffe |\n| 151 | Prometheus PX-2 | L | DGT 17, 25 m, Zone conique, Incendiaire, Surchauffe |\n| 152 | Null Lance IE-4 | L | DGT 14, 90 m, EMP, Perforant 1 ; mode faible DGT 8 ; Altération sur les capteurs, la mobilité ou l''arme d''une cible techno |\n| 153 | Judicator RL-5 | L | DGT 20, 180 m, Zone 5 m, Perforant 3 ; guidage par drone |\n| 154 | Blackstar GR-1 | X | DGT 18, 150 m, Zone 4 m, Perforant 2 ; Vigueur + Athlétisme contre 18 sinon une Altération gravitationnelle |\n| 155 | Ward M-6 | O | DGT 6, Perforant 3 ; outil de brèche |\n| 156 | Breacher B-9 | L | DGT 9, Perforant 3 ; profil complet en armure assistée |\n| 230 | Fulgur EB-7 | L | DGT 8, mêlée, Perforant 3 ; 1 PA pour l''allumer ; 10 scènes de cellule. *Validé par l''auteur le 1er octobre.* |\n| 231 | Duplex AR-12 | O | Assaut : DGT 16, 70 m, Automatique, Perforant 2. Dispersion : DGT 15, 20 m, Perforant 1, une cible. 1 PA pour changer. *Validé par l''auteur le 1er octobre.* |\n\n**Armures**\n\n| # | Objet | Niveau | Profil |\n|---|---|---|---|\n| 157 | Second Skin | D | Armure 4, sous les vêtements, auto-colmatage |\n| 158 | Vesper Recon | O | Armure 5 ; 1 PA : +3 pour se dissimuler aux capteurs visuels et thermiques ordinaires |\n| 159 | Urgent Matter | O | Armure 8, repliable (2 PA pour la déployer), hermétique, sans malus de mobilité |\n| 160 | Bastion | L | Armure 10, exoarmure ; porte les armes lourdes ; très visible |\n\n**Spécial TUC (Cohérence et confinement)**\n\n| # | Objet | Niveau | Fonction |\n|---|---|---|---|\n| 161 | ARGUS-T | S | Visière de cohérence, nécessaire à Calibration de cohérence |\n| 162 | Mnemosyne | S | Enregistreur invariant ; avec Chaîne invariante, détecte toute réécriture d''un flux relié |\n| 163 | STATOR | S | Avec Ancrage de terrain, Esprit + Technologie contre un changement d''état forcé d''une cible consentante |\n| 164 | CLEARSKY | S | Avec Fenêtre invariante : 2 PA, petite zone, observation instrumentale stable jusqu''à la fin du round suivant |\n| 165 | IRIS-0 | S/X | Optique de Vérité institutionnelle ; ne Révèle pas ; une HDS ou un Holojamer peut s''y opposer |\n| 166 | TRIAD-R | S | Trois capteurs : alerte sur une Révélation dans le volume (heure, secteur, intensité) |\n| 167 | TwinKey | S | Deux chaînes comparées ; signale qu''une réécriture a eu lieu |\n| 168 | Q-Lock | S | Périmètre de quarantaine journalisé ; ni prison ni barrière |\n| 169 | Needle-T | S | Drone sonde jetable, avec un ARGUS-T simplifié et une Mnemosyne miniature |\n| 170 | JANUS-B | S | Rend un capteur, un outil ou un contenant Biphysique pour une scène |\n| 171 | ARK-6 | S | Conteneur de confinement ; module JANUS possible |\n| 172 | SENTINEL-N | S | Alerte de possession ; révoque les accès sensibles ; aucune immunité |\n| 173 | WAKE-3 | S | 1 PA au contact : nouveau test contre un contrôle neurologique ; la cible devient Tendue et brièvement incapable |\n| 174 | HDS-4 Veil Lock | S/X | Empêche une cible V de passer en SR/R : elle doit réussir Volonté + Maîtrise spirituelle contre l''Esprit + Technologie de l''opérateur, sinon elle reste V. Aucun retour forcé de R à V. |\n| 175 | CALIBAN-S | S | Spectromètre de souillure matérielle ; ne lit pas la jauge d''un personnage |"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'catalogue_5_5', 'Calamitechnologie et reliques (#178 à #218)', NULL, '{"nature":"objets","numero":"5.5","texte":"Toutes les fiches de cette section restent telles quelles : elles sont déjà au bon format (Nature, profil, propriété, Souillure). Rappel par Source :\n\n- **Vhodhal** : Croc de la Faim (#178), Coffret de l''Inassouvi (#179), Munition affamée (#180), Extracteur entropique VHD-4 (#181), Grenade de Jeûne VHD-7 (#182), Effaceur VHD-0 (#183).\n- **V''Aagor** : Clou d''Annexe (#184), Lame de l''Interstice (#185), Cartouche interstitielle (#186), Mantelet de Non-Présence VAG-3 (#187), Variateur de Masse VAG-8 (#188), Gantelet de Fusion VAG-9 (#189), Passe-Mur VAG-12 (#190).\n- **Sharith** : Scalpel du Prisme (#191), Lentille des Jointures (#192), Munition délaminante (#193), Dissecteur SHR-11 (#194), Prismateur de Flux SHR-4 (#195), Charge prismatique SHR-7 (#196), Écran de Scission SHR-9 (#197).\n- **Vhadhi** : Clé Métastasique (#198), Manchette d''Interface Variable (#199), Masque de Survie Métastable (#200), Pont Fonctionnel VHI-5 (#201), Prothèse Métastable VHI-6 (#202), Réaffecteur d''Urgence VHI-7 (#203), Convertisseur Morphofonctionnel VHI-9 (#204).\n- **Shaoggith** : Graine Sentinelle (#205), Suture Vermiforme (#206), Carapace de Couvée (#207), Munition larvaire (#208), Nid instantané SHG-4 (#209), Capsule Outil-Graine SHG-6 (#210), Bioforge SHG-12 (#211).\n- **Thul** : Clou de Stase (#212), Munition Immuable (#213), Bracelet de Stase Médicale (#214), Coffre d''État THU-2 (#215), Boîte noire Abyssale THU-4 (#216), Projecteur Chronostatique THU-7 (#217), Grenade d''Inertie THU-9 (#218).\n\nChaque objet reprend un Don de sa Source, en plus faible ou plus étroit (par exemple Clou d''Annexe et Annexe sombre, Variateur de Masse et Poids impossible). C''est la logique de la Calamitechnologie : le principe est volé au Fléau et payé en Souillure. On ne touche à rien."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'catalogue_5_6', 'Hors catalogue', NULL, '{"nature":"objets","numero":"5.6","texte":"Ces objets n''ont ni prix ni rareté standard. On les obtient par la fiction, la campagne ou une quête, jamais en PTV.\n- **#43 Hors catalogue, Chasse** : armes de Merlin, Excalibur/Ymir, reliques divines majeures, artefacts de Hunt15, objets cosmologiques, compagnons, prototypes de PNJ.\n- **#86 Excalibur / Ymir** : relique unique de campagne.\n- **#131 Hors achat, marché xéno** : Cohérence AIDH moderne, armes de G-corporations non introduites, armes Feeshri à lien personnel, armes de vaisseau, FTL, artefacts uniques.\n- **#176 Calamitechnologie (statut)** : programme interdit ou expérimental (X), jamais une dotation.\n- **#219 à #223 Artefacts cosmiques** : Grande Orbe (Sharith), Nacres noires (Vhadhi), Nahfr (Shaoggith), Mue de Rulfam (Shaoggith), Lance de Longinus (V''Aagor ?, nature volontairement ouverte, aucun profil).\n\n---"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-22-proprietes-communes-des-equipements-de-verite', 'Propriétés communes des équipements de Vérité', NULL, '{"nature":"objets","chapitre":"22","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":[],"proprietes":[{"label":"Perforant X","value":"ignore X Armure matérielle seulement"},{"label":"Sacré","value":"consécration réelle ; vulnérabilités/Talents seulement"},{"label":"Angélique","value":"Sacré céleste ; divin si pertinent"},{"label":"Solaire","value":"effet surnaturel de Soleil ; UV ≠ Soleil"},{"label":"Incendiaire","value":"Feu ; Altération appropriée peut Enflammer"},{"label":"EMP / Ion","value":"affecte systèmes technologiques exposés"},{"label":"Invariant","value":"résiste aux corrections ordinaires ; ne voit rien de plus que son capteur"},{"label":"Calibré","value":"préparé contre une signature connue ; jamais universel"},{"label":"Surchauffe","value":"refroidissement après usage intensif selon profil"},{"label":"Verrouillé","value":"autorisation bio/psychique/nanitique/crypto requise"}],"lore":"Les équipements de Vérité obéissent à un vocabulaire technique partagé qui distingue clairement ce qui agit sur la matière, la technologie, le sacré ou la cohérence.","compendium":"verite-catalogue-001-proprietes-communes-des-equipements-de-verite","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
