INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-drill', 'Raven Drill', NULL, '{"nature":"objets","chapitre":"23","section":"Munitions de Chasse","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"Accès / prix","value":"A — 5 munitions pour le prix d’une boîte normale du calibre. Propriété Perforant 1."}],"lore":"A — 5 munitions pour le prix d’une boîte normale du calibre. Propriété Perforant 1.","compendium":"verite-catalogue-010-raven-drill","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
