INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-reliquary', 'Raven Reliquary', NULL, '{"nature":"objets","chapitre":"23","section":"Munitions de Chasse","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"Description","value":"A / GT-01 — prix ×2 — 5 munitions. Projectile creux destiné à transporter liquide, poudre ou matière rituelle. DGT −2. Si le tir inflige au moins 1 dégât réel, la substance est déposée dans la blessure. Ne se combine pas avec une autre munition spéciale."}],"lore":"A / GT-01 — prix ×2 — 5 munitions. Projectile creux destiné à transporter liquide, poudre ou matière rituelle. DGT −2. Si le tir inflige au moins 1 dégât réel, la substance est déposée dans la blessure. Ne se combine pas avec une autre munition spéciale.","compendium":"verite-catalogue-016-raven-reliquary","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-munition-angelique', 'Munition angélique', NULL, '{"nature":"objets","chapitre":"23","section":"Munitions de Chasse","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"Description","value":"T / A-GT-01 — environ prix ×3 pour 6 projectiles. Propriétés Sacré + Angélique. Aucun bonus de DGT générique. Peut exploiter une vraie faiblesse divine, affecter certaines manifestations spirituelles et servir de support aux Talents appropriés. Une profanation réelle peut supprimer ses propriétés sacrées sans détruire physiquement le projectile."}],"lore":"T / A-GT-01 — environ prix ×3 pour 6 projectiles. Propriétés Sacré + Angélique. Aucun bonus de DGT générique. Peut exploiter une vraie faiblesse divine, affecter certaines manifestations spirituelles et servir de support aux Talents appropriés. Une profanation réelle peut supprimer ses propriétés sacrées sans détruire physiquement le projectile.","compendium":"verite-catalogue-017-munition-angelique","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
