INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-gravewire', 'Raven Gravewire', NULL, '{"nature":"objets","chapitre":"23","section":"Capture physique","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"Description","value":"1 200 $ — A. Filet de capture renforcé, portée 10 m. Une réussite Entrave physiquement la cible. Le maillage peut recevoir un seul matériau préparé — argent, fer froid, support consacré ou autre — permettant d’exploiter une vulnérabilité réelle au contact prolongé."}],"lore":"1 200 $ — A. Filet de capture renforcé, portée 10 m. Une réussite Entrave physiquement la cible. Le maillage peut recevoir un seul matériau préparé — argent, fer froid, support consacré ou autre — permettant d’exploiter une vulnérabilité réelle au contact prolongé.","compendium":"verite-catalogue-026-raven-gravewire","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-no-witness', 'Raven « No Witness »', NULL, '{"nature":"objets","chapitre":"23","section":"Capture physique","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"Description","value":"450 $ — A. Capuche opaque, insonorisée et isolée des transmissions radio. Bloque réellement les vecteurs regard, voix, vision ou communication que sa conception empêche ; ne supprime aucune capacité sans vecteur."}],"lore":"450 $ — A. Capuche opaque, insonorisée et isolée des transmissions radio. Bloque réellement les vecteurs regard, voix, vision ou communication que sa conception empêche ; ne supprime aucune capacité sans vecteur.","compendium":"verite-catalogue-027-raven-no-witness","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-black-ark', 'Raven Black Ark', NULL, '{"nature":"objets","chapitre":"23","section":"Transport et confinement","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"Description","value":"1 800 $ — A / GT approprié. Conteneur rigide hermétique avec blindage électromagnétique, isolation thermique/radio et compartiment d’échantillonnage. Bloque les communications technologiques ordinaires ; aucune protection magique par défaut."}],"lore":"1 800 $ — A / GT approprié. Conteneur rigide hermétique avec blindage électromagnétique, isolation thermique/radio et compartiment d’échantillonnage. Bloque les communications technologiques ordinaires ; aucune protection magique par défaut.","compendium":"verite-catalogue-028-raven-black-ark","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-null-cage', 'Raven Null Cage', NULL, '{"nature":"objets","chapitre":"23","section":"Transport et confinement","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"6 500 $ — P / GT approprié. Cage modulaire devant être calibrée environ dix minutes contre un mode de fuite déjà identifié","value":"immatérialité, téléportation, projection spirituelle, transformation précise, extraction technologique ou mécanisme comparable. Une activation du mode calibré doit dépasser 18 ; si elle n’utilise normalement aucun jet, employer la Puissance de l’effet. Batterie environ 2 h. Un seul mode à la fois ; mauvais diagnostic = cage inutile ; une puissance supérieure peut la contourner ou la détruire."}],"lore":"6 500 $ — P / GT approprié. Cage modulaire devant être calibrée environ dix minutes contre un mode de fuite déjà identifié : immatérialité, téléportation, projection spirituelle, transformation précise, extraction technologique ou mécanisme comparable. Une activation du mode calibré doit dépasser 18 ; si elle n’utilise normalement aucun jet, employer la Puissance de l’effet. Batterie environ 2 h. Un seul mode à la fois ; mauvais diagnostic = cage inutile ; une puissance supérieure peut la contourner ou la détruire.","compendium":"verite-catalogue-029-raven-null-cage","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-byron-analyst', 'Byron « Analyst »', NULL, '{"nature":"objets","chapitre":"23","section":"Investigation","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"1 200 $ — C/A. Lunettes/capteurs augmentés","value":"IR, relief, dynamique, analyse de surface et détection technologique. Lorsque ces capteurs sont réellement pertinents : +3 favorable au test approprié de Perception/Investigation. Ne perce pas l’Hologramme."}],"lore":"1 200 $ — C/A. Lunettes/capteurs augmentés : IR, relief, dynamique, analyse de surface et détection technologique. Lorsque ces capteurs sont réellement pertinents : +3 favorable au test approprié de Perception/Investigation. Ne perce pas l’Hologramme.","compendium":"verite-catalogue-030-byron-analyst","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-dive-dsa-480', 'DIVE DSA-480', NULL, '{"nature":"objets","chapitre":"23","section":"Investigation","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"3 500 $ — C/A. Scanner de scène","value":"relief, couleur, chimie de surface, IR, UV et radio. Permet sur le terrain certains tests qui exigeraient normalement un laboratoire ; les Compétences restent nécessaires."}],"lore":"3 500 $ — C/A. Scanner de scène : relief, couleur, chimie de surface, IR, UV et radio. Permet sur le terrain certains tests qui exigeraient normalement un laboratoire ; les Compétences restent nécessaires.","compendium":"verite-catalogue-031-dive-dsa-480","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-drones-traqueurs-sct12', 'Drones traqueurs SCT12', NULL, '{"nature":"objets","chapitre":"23","section":"Investigation","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"Description","value":"2 000 $ les 10 — C/A. Petits drones terrestres capables de suivre forme, signal ou traceur dans une zone locale pendant environ quatre heures. Aucun suivi automatique d’âme, de téléportation ou de piste surnaturellement effacée."}],"lore":"2 000 $ les 10 — C/A. Petits drones terrestres capables de suivre forme, signal ou traceur dans une zone locale pendant environ quatre heures. Aucun suivi automatique d’âme, de téléportation ou de piste surnaturellement effacée.","compendium":"verite-catalogue-032-drones-traqueurs-sct12","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-mnemosyne', 'Raven « Mnemosyne »', NULL, '{"nature":"objets","chapitre":"23","section":"Investigation","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"4 800 $ — P / GT-00 ou GT-01 — Invariant. Caméra/enregistreur technomagique. Lorsqu’elle enregistre un phénomène réellement SR ou R, le fichier obtenu ne peut être ensuite réécrit par les corrections ordinaires de l’Hologramme. Si la cible était V lors de la prise, Mnemosyne enregistre la forme humaine cohérente","value":"elle préserve ce qui a été vu, elle ne perce pas le Voile."}],"lore":"4 800 $ — P / GT-00 ou GT-01 — Invariant. Caméra/enregistreur technomagique. Lorsqu’elle enregistre un phénomène réellement SR ou R, le fichier obtenu ne peut être ensuite réécrit par les corrections ordinaires de l’Hologramme. Si la cible était V lors de la prise, Mnemosyne enregistre la forme humaine cohérente : elle préserve ce qui a été vu, elle ne perce pas le Voile.","compendium":"verite-catalogue-033-raven-mnemosyne","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
