INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-shut-up-look-away', 'Raven « Shut Up & Look Away »', NULL, '{"nature":"objets","chapitre":"23","section":"Protections","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"Description","value":"900 $ — A. Masque/casque à visière occultante, obturateurs, isolation sonore et coupure rapide des flux numériques. 1 PA pour fermer ou rouvrir les canaux. Un pouvoir exigeant réellement un vecteur bloqué ne peut plus l’utiliser, mais le porteur perd lui aussi ce sens ou canal."}],"lore":"900 $ — A. Masque/casque à visière occultante, obturateurs, isolation sonore et coupure rapide des flux numériques. 1 PA pour fermer ou rouvrir les canaux. Un pouvoir exigeant réellement un vecteur bloqué ne peut plus l’utiliser, mais le porteur perd lui aussi ce sens ou canal.","compendium":"verite-catalogue-038-raven-shut-up-look-away","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-hse-11-daybreak', 'Raven HSE-11 « Daybreak »', NULL, '{"nature":"objets","chapitre":"23","section":"Prototypes Raven de Chasse","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"Description","value":"5 500 $ — P / GT-11 — Solaire. Émetteur technomagique portable. Déploiement 2 PA, maintien 1 PA/round, cône d’environ 10 m. Une cible terminant son activation directement exposée est considérée comme ayant subi un round de soleil direct. Maximum une exposition Solaire par round. Trois rounds d’autonomie avant refroidissement/recharge ; obstacle opaque réel = protection ; aucun effet particulier sur une créature sans faiblesse au soleil."}],"lore":"5 500 $ — P / GT-11 — Solaire. Émetteur technomagique portable. Déploiement 2 PA, maintien 1 PA/round, cône d’environ 10 m. Une cible terminant son activation directement exposée est considérée comme ayant subi un round de soleil direct. Maximum une exposition Solaire par round. Trois rounds d’autonomie avant refroidissement/recharge ; obstacle opaque réel = protection ; aucun effet particulier sur une créature sans faiblesse au soleil.","compendium":"verite-catalogue-039-raven-hse-11-daybreak","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-last-door', 'Raven « Last Door »', NULL, '{"nature":"objets","chapitre":"23","section":"Prototypes Raven de Chasse","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"6 500 $ — P / GT-33. Quatre balises calibrées sur une signature de transport technologique déjà observée","value":"téléportation, extraction, rappel orbital, phase ou équivalent. Déploiement 2 PA. Lorsqu’un système correspondant tente une extraction dans la zone, l’opérateur oppose Esprit + Technologie au système ; en réussite, cette extraction échoue. Aucun effet sur Magie, passage spirituel ou autre paradigme non calibré."}],"lore":"6 500 $ — P / GT-33. Quatre balises calibrées sur une signature de transport technologique déjà observée : téléportation, extraction, rappel orbital, phase ou équivalent. Déploiement 2 PA. Lorsqu’un système correspondant tente une extraction dans la zone, l’opérateur oppose Esprit + Technologie au système ; en réussite, cette extraction échoue. Aucun effet sur Magie, passage spirituel ou autre paradigme non calibré.","compendium":"verite-catalogue-040-raven-last-door","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-raven-murder-box', 'Raven « Murder Box »', NULL, '{"nature":"objets","chapitre":"23","section":"Prototypes Raven de Chasse","statut_catalogue":"catalogue","origine":"catalogue","tags":["Chasse"],"proprietes":[{"label":"Description","value":"3 500 $ — P/A. Mallette de quatre microdrones thermique, radio, chimique et optique. Le Chasseur peut résoudre un test depuis le meilleur point de perception réel du réseau. Aucun bonus cumulatif et aucune attaque indépendante."}],"lore":"3 500 $ — P/A. Mallette de quatre microdrones thermique, radio, chimique et optique. Le Chasseur peut résoudre un test depuis le meilleur point de perception réel du réseau. Aucun bonus cumulatif et aucune attaque indépendante.","compendium":"verite-catalogue-041-raven-murder-box","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-23-equipement-typique-des-traditions', 'Équipement typique des traditions', NULL, '{"nature":"objets","chapitre":"23","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":[],"proprietes":[{"label":"Catholiques","value":"Eau bénite, balles angéliques, sel, reliques, armes consacrées."},{"label":"Kabbalistes","value":"Balles angéliques, supports d’inscription, plaques et sceaux."},{"label":"Nizarites","value":"Balles angéliques, matériel de pacte, supports du Djinn."},{"label":"Khālsā","value":"Arme personnelle consacrée, huiles et supports rituels."},{"label":"Taoïstes Gu/Shimazu","value":"Matériel méditatif et rituel léger."},{"label":"Shi","value":"Ancrages et supports de scellement."},{"label":"Onmyoji","value":"Ofuda, encres et supports de sceaux."},{"label":"Néopaïens","value":"Offrandes, symboles et correspondances."},{"label":"Chasse Fantastique","value":"Monture/véhicule et armement de chasse."},{"label":"Lueurs d’Azménor","value":"Peu de matériel obligatoire ; supports du Néant selon tradition."},{"label":"Xenoshield","value":"Analyseurs, cages, brouilleurs, prélèvements et systèmes d’interception."},{"label":"Table Ronde","value":"Arme de Merlin unique de la lignée."},{"label":"Indépendants","value":"Aucune norme."}],"lore":"Chaque tradition de Chasse privilégie des supports qui reflètent sa doctrine, ses rites et sa manière d’affronter l’invisible.","compendium":"verite-catalogue-042-equipement-typique-des-traditions","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-23-hors-catalogue-equipement-de-chasse', 'Hors catalogue — Équipement de Chasse', NULL, '{"nature":"objets","chapitre":"23","section":"Référence","statut_catalogue":"hors_catalogue","origine":"reference","tags":[],"proprietes":[{"label":"Statut","value":"Hors acquisition standard"},{"label":"Éléments","value":"Aucun prix ni niveau de rareté standard pour : armes de Merlin ; Excalibur/Ymir ; reliques divines majeures ; artefacts personnels de Hunt15 ; objets cosmologiques ; compagnons et entités surnaturelles ; prototypes uniques de PNJ. Ces éléments relèvent de la fiction, de la campagne ou d’un autre catalogue spécialisé, jamais d’un achat en PTV."}],"lore":"Certaines armes, reliques et entités ne relèvent jamais d’un achat ordinaire, même dans les réseaux de Chasse.","compendium":"verite-catalogue-043-hors-catalogue-equipement-de-chasse","mj":true}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-plaque-de-fer', 'Plaque de Fer', NULL, '{"nature":"objets","chapitre":"24","section":"Armement runique whurten","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Petite plaque gravée à fixer sur une arme ou un outil."},{"label":"Accès / prix","value":"V1 - 1 500 $ - charge runique"},{"label":"Activation","value":"1 PA ; pour la scène, l’objet peut interagir normalement avec une Ombre, une manifestation immatérielle ou un effet explicitement intangible."},{"label":"Limite","value":"Aucun bonus d’attaque ou de dégâts ; la charge s’éteint à la fin de la scène."}],"lore":"Petite plaque gravée à fixer sur une arme ou un outil.","compendium":"verite-catalogue-044-plaque-de-fer","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-lame-de-fer-stabilisee', 'Lame de Fer stabilisée', NULL, '{"nature":"objets","chapitre":"24","section":"Armement runique whurten","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Épée, hache, marteau ou autre arme durable portant une Rune de Fer stabilisée."},{"label":"Accès / prix","value":"V2 - 8 000 $ + arme - inscription d’atelier"},{"label":"Effet","value":"Biphysique : la fonction physique de l’arme peut atteindre les manifestations immatérielles accessibles."},{"label":"Entretien","value":"Après destruction sérieuse, modification lourde de la lame ou neutralisation runique, un runiste doit restaurer l’inscription."},{"label":"DGT","value":"Utilise le DGT normal de l’arme de base."}],"lore":"Épée, hache, marteau ou autre arme durable portant une Rune de Fer stabilisée.","compendium":"verite-catalogue-045-lame-de-fer-stabilisee","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-marteau-de-scellement', 'Marteau de Scellement', NULL, '{"nature":"objets","chapitre":"24","section":"Armement runique whurten","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Marteau lourd comportant une matrice de Scellement et des pointes-supports."},{"label":"Accès / prix","value":"V2 - 12 000 $ - outil/arme runique"},{"label":"Profil","value":"DGT 7 en mêlée."},{"label":"Scellement","value":"Hors attaque, 1 PA pour fixer une pointe sur une porte, un contenant ou une jonction fermée. Jusqu’à la fin de la scène, toute ouverture par force, magie ou immatérialité exige une action et un test approprié contre difficulté 18."},{"label":"Limite","value":"Le support peut être détruit matériellement."}],"lore":"Marteau lourd comportant une matrice de Scellement et des pointes-supports.","compendium":"verite-catalogue-046-marteau-de-scellement","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-brigandine-de-garde', 'Brigandine de Garde', NULL, '{"nature":"objets","chapitre":"24","section":"Armement runique whurten","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Protection discrète portant une Rune de Garde stabilisée à charge unique."},{"label":"Accès / prix","value":"V2 - 15 000 $ - Armure 2"},{"label":"Armure","value":"2 contre les dégâts matériels selon les règles normales."},{"label":"Rune","value":"La première source de dégâts surnaturels du scénario est réduite de 3, minimum 0, puis la charge runique s’éteint."}],"lore":"Protection discrète portant une Rune de Garde stabilisée à charge unique.","compendium":"verite-catalogue-047-brigandine-de-garde","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-verrou-nibelungen', 'Verrou Nibelungen', NULL, '{"nature":"objets","chapitre":"24","section":"Armement runique whurten","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Boîtier, menottes ou coffret utilisant une plaque de Scellement."},{"label":"Accès / prix","value":"V1 - 4 000 $"},{"label":"Effet","value":"Une ouverture par force, magie ou immatérialité exige une action et un test approprié contre difficulté 18."},{"label":"Usage","value":"Ne rend pas le contenant indestructible : casser le mur, la boîte ou le poignet reste une solution physique si la fiction le permet."}],"lore":"Boîtier, menottes ou coffret utilisant une plaque de Scellement.","compendium":"verite-catalogue-048-verrou-nibelungen","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-plaque-de-veille', 'Plaque de Veille', NULL, '{"nature":"objets","chapitre":"24","section":"Armement runique whurten","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Support runique à coller sur passage, porte, véhicule ou objet."},{"label":"Accès / prix","value":"V1 - 1 000 $"},{"label":"Effet","value":"À l’activation, définir une condition simple : franchi, déplacé, ouvert, retiré. Le porteur de la clé runique reçoit une alerte mentale lorsque la condition se produit."},{"label":"Charge","value":"Une scène ou jusqu’au déclenchement, puis recharge nécessaire."}],"lore":"Support runique à coller sur passage, porte, véhicule ou objet.","compendium":"verite-catalogue-049-plaque-de-veille","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-projectile-de-fer', 'Projectile de Fer', NULL, '{"nature":"objets","chapitre":"24","section":"Munitions et charges runiques","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Effet","value":"Munition à usage unique : le tir est Biphysique et peut affecter une manifestation immatérielle accessible. Aucun bonus de DGT."},{"label":"Prix","value":"250 $ / projectile"}],"lore":"Munition à usage unique : le tir est Biphysique et peut affecter une manifestation immatérielle accessible. Aucun bonus de DGT.","compendium":"verite-catalogue-050-projectile-de-fer","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-tete-de-scellement', 'Tête de Scellement', NULL, '{"nature":"objets","chapitre":"24","section":"Munitions et charges runiques","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Effet","value":"Projectile non létal ou carreau : s’il se fixe sur un support/objet, il déploie un Scellement difficulté 15 jusqu’à la fin du round suivant."},{"label":"Prix","value":"600 $"}],"lore":"Projectile non létal ou carreau : s’il se fixe sur un support/objet, il déploie un Scellement difficulté 15 jusqu’à la fin du round suivant.","compendium":"verite-catalogue-051-tete-de-scellement","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-ruban-de-veille', 'Ruban de Veille', NULL, '{"nature":"objets","chapitre":"24","section":"Munitions et charges runiques","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Effet","value":"Bande pré-gravée : alerte une clé runique si elle est coupée ou franchie. Usage unique."},{"label":"Prix","value":"300 $"}],"lore":"Bande pré-gravée : alerte une clé runique si elle est coupée ou franchie. Usage unique.","compendium":"verite-catalogue-052-ruban-de-veille","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-jeton-de-garde', 'Jeton de Garde', NULL, '{"nature":"objets","chapitre":"24","section":"Munitions et charges runiques","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Effet","value":"À briser en Réaction contre une source de dégâts surnaturels : réduit ces dégâts de 2. Usage unique."},{"label":"Prix","value":"750 $"}],"lore":"À briser en Réaction contre une source de dégâts surnaturels : réduit ces dégâts de 2. Usage unique.","compendium":"verite-catalogue-053-jeton-de-garde","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-capteur-biphysique-portatif', 'Capteur biphysique portatif', NULL, '{"nature":"objets","chapitre":"24","section":"Technomagie azménorienne — Convergence","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Scanner ou caméra capable de détecter plusieurs familles de phénomènes normalement absents des capteurs ordinaires."},{"label":"Accès / prix","value":"V2 - 12 000 $"},{"label":"Effet","value":"Détecte magie active, perturbations importantes du Flux, phénomènes immatériels directement présents et anomalies dimensionnelles locales."},{"label":"Limite","value":"Indique qu’un phénomène existe sans donner automatiquement sa nature, son auteur ou ses pouvoirs."}],"lore":"Scanner ou caméra capable de détecter plusieurs familles de phénomènes normalement absents des capteurs ordinaires.","compendium":"verite-catalogue-054-capteur-biphysique-portatif","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-relais-de-declenchement-croise', 'Relais de déclenchement croisé', NULL, '{"nature":"objets","chapitre":"24","section":"Technomagie azménorienne — Convergence","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Boîtier reliant une fonction technologique à un événement surnaturel reconnu par un capteur biphysique."},{"label":"Accès / prix","value":"V2 - 18 000 $"},{"label":"Exemples","value":"Fermer une porte, déclencher une alarme, démarrer un enregistreur, couper un circuit lorsqu’une anomalie apparaît."},{"label":"Interdit","value":"Ne réalise jamais automatiquement une attaque contre une cible."}],"lore":"Boîtier reliant une fonction technologique à un événement surnaturel reconnu par un capteur biphysique.","compendium":"verite-catalogue-055-relais-de-declenchement-croise","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-convertisseur-biphysique-de-secours', 'Convertisseur biphysique de secours', NULL, '{"nature":"objets","chapitre":"24","section":"Technomagie azménorienne — Convergence","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Prototype permettant à un utilisateur initié ou à une source magique compatible d’alimenter brièvement une fonction technologique."},{"label":"Accès / prix","value":"V3 - 55 000 $"},{"label":"Usage sans technomage","value":"Le boîtier doit avoir été calibré sur une source précise ; 1/Scène, il peut convertir une charge magique préstockée pour alimenter un appareil portatif pendant un round."},{"label":"Usage technomage","value":"Un praticien connaissant Convertisseur biphysique utilise normalement son Talent avec le dispositif."},{"label":"Limite","value":"Jamais propulsion principale, industrie ou arme lourde énergétique."}],"lore":"Prototype permettant à un utilisateur initié ou à une source magique compatible d’alimenter brièvement une fonction technologique.","compendium":"verite-catalogue-056-convertisseur-biphysique-de-secours","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-relais-discontinu', 'Relais discontinu', NULL, '{"nature":"objets","chapitre":"24","section":"Technomagie azménorienne — Fracture","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Émetteur/récepteur conçu pour établir une liaison à très courte distance à travers un obstacle matériel."},{"label":"Accès / prix","value":"V2 - 15 000 $"},{"label":"Effet","value":"1 PA : liaison de données/commande avec un appareil connu situé à moins d’1 mètre, même derrière mur ou blindage."},{"label":"Limite","value":"Ne contourne ni chiffrement, ni mot de passe, ni appareil éteint."}],"lore":"Émetteur/récepteur conçu pour établir une liaison à très courte distance à travers un obstacle matériel.","compendium":"verite-catalogue-057-relais-discontinu","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-optique-de-phase', 'Optique de phase', NULL, '{"nature":"objets","chapitre":"24","section":"Technomagie azménorienne — Fracture","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Capteur à dérivation spatiale créant un chemin sensoriel étroit à travers la matière."},{"label":"Accès / prix","value":"V2 - 28 000 $ - 1/Scène"},{"label":"Effet","value":"1 PA : pendant un round, le capteur voit/mesure à travers jusqu’à 1 mètre de matière non surnaturelle."},{"label":"Limite","value":"La caméra ne produit que les données qu’elle saurait normalement produire ; aucune vision omnisciente."}],"lore":"Capteur à dérivation spatiale créant un chemin sensoriel étroit à travers la matière.","compendium":"verite-catalogue-058-optique-de-phase","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-module-de-trajectoire-decalee', 'Module de trajectoire décalée', NULL, '{"nature":"objets","chapitre":"24","section":"Technomagie azménorienne — Fracture","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Projecteur monté sur une arme à distance."},{"label":"Accès / prix","value":"V3 - 45 000 $ - arme préparée"},{"label":"Effet","value":"1/Scène, avant un tir, déplace le point de sortie de la trajectoire jusqu’à 1 mètre. Permet de contourner un angle ou le bord d’un Couvert partiel."},{"label":"Limite","value":"Il faut réellement percevoir la cible ou disposer de données suffisantes pour la viser. Aucun bonus d’attaque ou de dégâts."}],"lore":"Projecteur monté sur une arme à distance.","compendium":"verite-catalogue-059-module-de-trajectoire-decalee","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-kit-microbreche', 'Kit Microbrèche', NULL, '{"nature":"objets","chapitre":"24","section":"Technomagie azménorienne — Fracture","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Installation portative ouvrant une fenêtre d’environ 20 cm entre deux points séparés par au maximum 1 mètre de matière."},{"label":"Accès / prix","value":"V4 - 120 000 $ - très restreint"},{"label":"Activation","value":"3 PA, 1/Scénario sans maintenance spécialisée."},{"label":"Passage","value":"Lumière, son, signaux, câbles, petits objets, outils et projectiles."},{"label":"Interdits","value":"Aucune créature vivante ou membre vivant ; jamais à l’intérieur d’un organisme ; la fermeture ne tranche rien."}],"lore":"Installation portative ouvrant une fenêtre d’environ 20 cm entre deux points séparés par au maximum 1 mètre de matière.","compendium":"verite-catalogue-060-kit-microbreche","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-optique-de-verite', 'Optique de Vérité', NULL, '{"nature":"objets","chapitre":"24","section":"Arsenal de Rupture — voir et agir sous le Voile","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Lunette, caméra, viseur ou scanner technomagique interprétant la scène sous le Voile."},{"label":"Accès / prix","value":"V3 - 35 000 $ - très surveillée"},{"label":"Effet","value":"Montre la nature et la morphologie véritables d’une cible V/SR/R dans son champ."},{"label":"Important","value":"Voir sous le Voile ne Révèle jamais la cible. La cible conserve son état, ses caractéristiques et ses Talents de forme."},{"label":"Limite","value":"Ne révèle ni pouvoirs, ni intentions, ni nom, ni identité exacte. Une HDS adaptée peut s’y opposer."}],"lore":"Lunette, caméra, viseur ou scanner technomagique interprétant la scène sous le Voile.","compendium":"verite-catalogue-061-optique-de-verite","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-enregistreur-invariant', 'Enregistreur invariant', NULL, '{"nature":"objets","chapitre":"24","section":"Arsenal de Rupture — voir et agir sous le Voile","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Stockage technomagique protégé contre la correction ordinaire de l’Hologramme."},{"label":"Accès / prix","value":"V3 - 45 000 $"},{"label":"Effet","value":"Conserve les données telles qu’elles ont réellement été captées."},{"label":"Synergie","value":"Avec une Optique de Vérité, l’enregistrement conserve la morphologie vraie."},{"label":"Limite","value":"Peut toujours être détruit, piraté ou neutralisé par une contre-mesure spécifique."}],"lore":"Stockage technomagique protégé contre la correction ordinaire de l’Hologramme.","compendium":"verite-catalogue-062-enregistreur-invariant","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-scanner-de-signature-de-verite', 'Scanner de Signature de Vérité', NULL, '{"nature":"objets","chapitre":"24","section":"Arsenal de Rupture — voir et agir sous le Voile","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Capteur permettant de reconnaître un individu déjà observé avec une Optique de Vérité."},{"label":"Accès / prix","value":"V3 - 55 000 $ - calibré"},{"label":"Calibration","value":"Quelques minutes d’observation et enregistrement de sa signature de continuité."},{"label":"Effet","value":"Reconnaît ensuite le même individu lorsqu’il passe réellement dans le champ, malgré changement d’apparence ou état V/SR/R."},{"label":"Limite","value":"Pas de localisation à distance."}],"lore":"Capteur permettant de reconnaître un individu déjà observé avec une Optique de Vérité.","compendium":"verite-catalogue-063-scanner-de-signature-de-verite","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-fenetre-de-verite', 'Fenêtre de Vérité', NULL, '{"nature":"objets","chapitre":"24","section":"Arsenal de Rupture — voir et agir sous le Voile","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Installation technomagique de pièce produisant en temps réel une représentation locale complète sous le Voile."},{"label":"Accès / prix","value":"V4 - 130 000 $ - installation"},{"label":"Zone","value":"Quelques mètres / une petite pièce selon installation."},{"label":"Effet","value":"Les écrans et viseurs reliés montrent la scène véritable."},{"label":"Limite","value":"Ne Révèle personne et n’éteint jamais l’Hologramme."}],"lore":"Installation technomagique de pièce produisant en temps réel une représentation locale complète sous le Voile.","compendium":"verite-catalogue-064-fenetre-de-verite","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-module-d-interference', 'Module d’Interférence', NULL, '{"nature":"objets","chapitre":"24","section":"Arsenal de Rupture — voir et agir sous le Voile","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Adaptation rendant une arme simultanément reconnue par la matière et par certains phénomènes immatériels."},{"label":"Accès / prix","value":"V2 - +20 000 $ à une arme"},{"label":"Effet","value":"L’arme devient Biphysique et peut affecter Ombres, entités déphasées et phénomènes explicitement intangibles accessibles."},{"label":"Profil","value":"DGT, portée et jet restent ceux de l’arme de base."},{"label":"Limite","value":"Aucun bonus de détection ni de dégâts."}],"lore":"Adaptation rendant une arme simultanément reconnue par la matière et par certains phénomènes immatériels.","compendium":"verite-catalogue-065-module-d-interference","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-ancre-d-ombre', 'Ancre d’Ombre', NULL, '{"nature":"objets","chapitre":"24","section":"Arsenal de Rupture — voir et agir sous le Voile","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Générateur créant une zone de stabilité locale."},{"label":"Accès / prix","value":"V3 - 50 000 $ - générateur de champ"},{"label":"Zone","value":"Environ 3 m de rayon."},{"label":"Effet","value":"Une Ombre ou créature immatérielle qui tente de quitter le plan, se dématérialiser, franchir la limite sous forme immatérielle ou rompre son ancrage doit réussir Volonté + Force mentale contre difficulté 18. Échec : action et coût perdus."},{"label":"Limite","value":"Ne bloque pas les mouvements physiques normaux."}],"lore":"Générateur créant une zone de stabilité locale.","compendium":"verite-catalogue-066-ancre-d-ombre","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
