INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-module-de-desancrage', 'Module de Désancrage', NULL, '{"nature":"objets","chapitre":"24","section":"Arsenal de Rupture — voir et agir sous le Voile","statut_catalogue":"catalogue","origine":"catalogue","tags":["Exilés"],"proprietes":[{"label":"Description","value":"Module offensif très rare destiné à clouer une manifestation à son support actuel."},{"label":"Accès / prix","value":"V4 - +60 000 $ à une arme d’Interférence"},{"label":"Effet","value":"1/Scène par cible, après un coup réussi sur une cible reposant sur un ancrage surnaturel, elle oppose Volonté + Force mentale à difficulté 18. Échec : jusqu’à la fin de la scène, elle ne peut plus redevenir immatérielle, quitter le plan par sa capacité naturelle ni changer d’hôte/support via cet ancrage."},{"label":"Limite","value":"Aucun effet supplémentaire sur une créature sans mécanique d’ancrage."}],"lore":"Module offensif très rare destiné à clouer une manifestation à son support actuel.","compendium":"verite-catalogue-068-module-de-desancrage","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
