INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-24-runes-de-marche', 'Runes de marché', NULL, '{"nature":"objets","chapitre":"24","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":[],"proprietes":[{"label":"Principe","value":"Les runes personnelles d’un praticien restent soumises aux règles de la voie whurtenne. Pour la vente, les ateliers fabriquent surtout des supports à charge stabilisée : l’effet est fixe, l’acheteur peut l’activer, puis la charge doit être restaurée par un runiste. Cela évite qu’un non-praticien transporte une collection infinie de runes permanentes."},{"label":"Plaque runique","value":"Activation 1 PA. Fonctionne jusqu’à la fin de la scène ou jusqu’à consommation de son effet."},{"label":"Inscription d’atelier","value":"Objet plus rare : fonction passive fixe, mais ne peut être reconfigurée. Une rupture du support exige un runiste pour la restaurer."},{"label":"Recharge","value":"Quelques minutes à plusieurs heures selon l’objet ; généralement incluse dans le prix d’entretien, pas réalisable sans savoir-faire runique."}],"lore":"Les ateliers whurtens vendent surtout des supports à charge stabilisée, pensés pour transmettre une fonction fixe sans donner au porteur le savoir du runiste.","compendium":"verite-catalogue-085-runes-de-marche","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-24-excalibur-ymir', 'Excalibur / Ymir', NULL, '{"nature":"objets","chapitre":"24","section":"Artefacts et matériels hors catalogue","statut_catalogue":"unique","origine":"artifact","tags":["Artefact unique","Table Ronde"],"proprietes":[{"label":"Statut","value":"Relique unique de campagne ; aucun prix ni niveau de rareté standard dans ce catalogue."},{"label":"Accès","value":"Fiction, héritage, quête ou événement exceptionnel ; jamais un achat en PTV."}],"lore":"Excalibur et Ymir appartiennent aux reliques dont la possession relève de l’histoire des lignées et des événements majeurs, pas d’un marché.","compendium":"verite-catalogue-086-excalibur-ymir","mj":true}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
