INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-25-go-02', 'GO-02', NULL, '{"nature":"objets","chapitre":"25","section":"Armement rocréen et Feeshri","statut_catalogue":"catalogue","origine":"catalogue","tags":["Xéno"],"proprietes":[{"label":"Description","value":"Poignée entourée de deux anneaux de champ, auto-alimentée, projetant une décharge combinant lumière cohérente et électricité."},{"label":"Accès / prix","value":"M3 - 1 500 000 Dykal - reliquat rocréen"},{"label":"Profil","value":"DGT 6, portée 60 m, Laser + EMP, Auto-alimenté."},{"label":"Particularité","value":"Aucune munition conventionnelle. Les dégâts restent normaux contre une cible sans composant électronique."},{"label":"Rareté","value":"Les exemplaires complets sont anciens, recherchés et politiquement sensibles."}],"lore":"Poignée entourée de deux anneaux de champ, auto-alimentée, projetant une décharge combinant lumière cohérente et électricité.","compendium":"verite-catalogue-104-go-02","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-25-resonateur-feeshri-de-volonte', 'Résonateur Feeshri de volonté', NULL, '{"nature":"objets","chapitre":"25","section":"Armement rocréen et Feeshri","statut_catalogue":"catalogue","origine":"catalogue","tags":["Xéno"],"proprietes":[{"label":"Accès / prix","value":"M3/M4 - prix variable - Psychique, Verrouillé"},{"label":"Arme-amplificateur mentale. Elle ne produit pas une attaque autonome","value":"elle donne une structure et une portée instrumentale à un pouvoir psychique compatible."},{"label":"Effet","value":"Un pouvoir mental du porteur normalement limité à courte portée peut être canalisé jusqu’à 50 m si la cible reste perceptible par le viseur. Même PA, même jet, même Défense occulte."},{"label":"Limite","value":"N’accorde aucun pouvoir psychique et n’augmente pas les dégâts."},{"label":"Compatibilité","value":"Le verrou Feeshri repose souvent sur une signature mentale individuelle ; le désactiver est un projet à part entière."}],"lore":"Arme-amplificateur mentale. Elle ne produit pas une attaque autonome : elle donne une structure et une portée instrumentale à un pouvoir psychique compatible.","compendium":"verite-catalogue-105-resonateur-feeshri-de-volonte","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-25-carabine-feeshri-n-ud-bleu', 'Carabine Feeshri « Nœud bleu »', NULL, '{"nature":"objets","chapitre":"25","section":"Armement rocréen et Feeshri","statut_catalogue":"catalogue","origine":"catalogue","tags":["Xéno"],"proprietes":[{"label":"Description","value":"Amplificateur collectif de contrôle mental, rare même chez les Feeshri."},{"label":"Accès / prix","value":"M4 - importation G-corporation - Psychique"},{"label":"Effet","value":"À condition que l’utilisateur possède déjà un pouvoir de domination ou d’intrusion mentale, il peut sélectionner deux cibles proches l’une de l’autre avec la même activation 1/Scène. Chaque cible oppose sa propre Défense occulte."},{"label":"Limite","value":"L’effet de base n’est jamais renforcé et une cible non valide pour le pouvoir reste non valide."},{"label":"Marché","value":"Objet de mission ou de dette majeure, pas un achat de routine."}],"lore":"Amplificateur collectif de contrôle mental, rare même chez les Feeshri.","compendium":"verite-catalogue-106-carabine-feeshri-n-ud-bleu","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
