INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-25-tk-x', 'TK X', NULL, '{"nature":"objets","chapitre":"25","section":"Armement Ad’rak, Xewen et Ménomah","statut_catalogue":"catalogue","origine":"catalogue","tags":["Xéno"],"proprietes":[{"label":"Description","value":"Canon à sphères électriques maintenu par des arcs métalliques en suspension magnétique."},{"label":"Accès / prix","value":"M3 - 50 000 Dykal - arme Xewen"},{"label":"Profil","value":"DGT 8, portée 70 m, EMP."},{"label":"Instabilité","value":"Après un échec narratif, l’arme se désassemble partiellement : 2 PA de remise en place avec accès direct."},{"label":"Ergonomie","value":"Très lourde et conçue pour une morphologie Xewen."}],"lore":"Canon à sphères électriques maintenu par des arcs métalliques en suspension magnétique.","compendium":"verite-catalogue-115-tk-x","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-25-tanax-alpha', 'Tanax Alpha', NULL, '{"nature":"objets","chapitre":"25","section":"Armement Ad’rak, Xewen et Ménomah","statut_catalogue":"catalogue","origine":"catalogue","tags":["Xéno"],"proprietes":[{"label":"Description","value":"Canon à ondes modulables développé pour des méchanoïdes."},{"label":"Accès / prix","value":"M3 - 75 000 Dykal - arme ménomah"},{"label":"Mode cinétique","value":"DGT 7, portée 60 m."},{"label":"Mode perturbation","value":"DGT 5, EMP ; contre un drone ou robot, l’Altération peut viser ses capteurs ou sa mobilité."},{"label":"Alimentation","value":"Environ 50 heures d’usage intermittent avant révision de la source."}],"lore":"Canon à ondes modulables développé pour des méchanoïdes.","compendium":"verite-catalogue-116-tanax-alpha","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-25-pistolet-aidh-2e-generation', 'Pistolet AIDH — 2e génération', NULL, '{"nature":"objets","chapitre":"25","section":"Contrabande AIDH","statut_catalogue":"catalogue","origine":"catalogue","tags":["Xéno"],"proprietes":[{"label":"Accès / prix","value":"M3 - 45 000 Dykal équivalent - Verrouillé"},{"label":"Ancien pistolet à générateur de projectiles","value":"une cartouche de matière remplace un chargeur conventionnel."},{"label":"Profil","value":"DGT 7, portée 35 m, Perforant 1, réserve 200 tirs."},{"label":"Logistique","value":"La cartouche-source est spécialisée ; la remplacer par des matériaux improvisés demande une vraie compétence/technique adaptée."}],"lore":"Ancien pistolet à générateur de projectiles : une cartouche de matière remplace un chargeur conventionnel.","compendium":"verite-catalogue-117-pistolet-aidh-2e-generation","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-25-fusil-aidh-1re-generation', 'Fusil AIDH — 1re génération', NULL, '{"nature":"objets","chapitre":"25","section":"Contrabande AIDH","statut_catalogue":"catalogue","origine":"catalogue","tags":["Xéno"],"proprietes":[{"label":"Description","value":"Fusil d’assaut ancien capable de modifier son régime de tir."},{"label":"Accès / prix","value":"M3 - 200 000 Dykal équivalent - Verrouillé"},{"label":"Mode automatique","value":"DGT 8, portée 80 m, compatible Tir de suppression."},{"label":"Mode perforant","value":"DGT 10, portée 70 m, Perforant 2, tir unique."},{"label":"Capteurs","value":"Certains exemplaires intègrent viseur thermique ou assistance de cible ; aucun ne voit sous l’Hologramme par défaut."}],"lore":"Fusil d’assaut ancien capable de modifier son régime de tir.","compendium":"verite-catalogue-118-fusil-aidh-1re-generation","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-pastille-d-armement-aidh-1re-generation', 'Pastille d’armement AIDH - 1re génération', NULL, '{"nature":"objets","chapitre":"26","section":"Matériel hors dotation normale · Contrabande AIDH","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Contrabande xéno","Xéno"],"proprietes":[{"label":"Description","value":"Pastille neuro-connectée de première génération capable de matérialiser autour de la main plusieurs configurations d’armes mémorisées."},{"label":"Accès / prix","value":"M4 - 2 000 000 Dykal minimum - implant/artefact technologique"},{"label":"Limite","value":"À l’acquisition, définir au maximum trois configurations d’armes réelles stockées dans la matrice. Changer de configuration : 1 PA."},{"label":"Profil","value":"Chaque configuration utilise son propre profil normal ; aucune munition spéciale gratuite."},{"label":"Fiabilité","value":"Sur un échec narratif impliquant la pastille, elle se verrouille jusqu’à réparation ou réinitialisation."},{"label":"Rareté","value":"Objet de scénario, de vol ou de dette exceptionnelle ; pas un produit courant du marché Shaediri."},{"label":"Description","value":"Ancienne pastille neuro-connectée capable de matérialiser autour de la main plusieurs configurations d’armes mémorisées."},{"label":"Classification","value":"Artefact technologique · X"},{"label":"Limite","value":"définir au maximum trois configurations réelles ; changement 1 PA"},{"label":"Profil","value":"chaque configuration utilise son profil normal ; aucune munition spéciale gratuite"},{"label":"Fiabilité","value":"sur un échec narratif lié à la pastille, verrouillage jusqu’à réparation/réinitialisation"},{"label":"Limites","value":"Objet de scénario, de vol ou de dette exceptionnelle ; l’AIDH moderne n’en distribue pas comme dotation standard."}],"lore":"Ancienne pastille neuro-connectée capable de matérialiser plusieurs configurations d’armes mémorisées ; elle circule surtout par récupération, vol ou dette exceptionnelle.","compendium":"verite-catalogue-119-pastille-d-armement-aidh-1re-generation","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
