INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-25-cartouche-de-matiere-aidh-ancienne', 'Cartouche de matière AIDH ancienne', NULL, '{"nature":"objets","chapitre":"25","section":"Modules et consommables du marché xéno","statut_catalogue":"catalogue","origine":"catalogue","tags":["Xéno"],"proprietes":[{"label":"Effet","value":"Recharge pour générateur de projectiles de première/deuxième génération."},{"label":"Prix / accès","value":"5 000 à 20 000 Dykal / M3"}],"lore":"Recharge pour générateur de projectiles de première/deuxième génération.","compendium":"verite-catalogue-130-cartouche-de-matiere-aidh-ancienne","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-25-ce-qui-n-est-pas-un-achat-normal-marche-xeno', 'Ce qui n’est pas un achat normal — Marché xéno', NULL, '{"nature":"objets","chapitre":"25","section":"Référence","statut_catalogue":"hors_catalogue","origine":"reference","tags":[],"proprietes":[{"label":"Statut","value":"Hors achat normal"},{"label":"Éléments","value":"technologies AIDH modernes de Cohérence et systèmes centraux de l''Hologramme ; armes de G-corporations encore non introduites sur Terre en série ; armes Feeshri exigeant un lien psychique personnel non contournable ; armes de vaisseau, moteurs FTL, systèmes de transit interstellaire ou installations industrielles ; artefacts uniques, prototypes nommés de PNJ ou équipements dont l’existence elle-même constitue un secret de scénario."}],"lore":"Même dans la contrebande xéno, certaines technologies restent trop stratégiques, trop personnelles ou trop dangereuses pour devenir de simples marchandises.","compendium":"verite-catalogue-131-ce-qui-n-est-pas-un-achat-normal-marche-xeno","mj":true}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-25-ergonomie-etrangere', 'Ergonomie étrangère', NULL, '{"nature":"objets","chapitre":"25","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":[],"proprietes":[{"label":"Règle","value":"Une arme conçue pour une autre morphologie, un autre système nerveux ou une autre interface peut être physiquement utilisable sans être réellement adaptée. Tant que l’objet n’a pas été modifié : ergonomie seulement inhabituelle : circonstances défavorables (-3) aux actions exigeant précision ou manipulation rapide ; interface biométrique ou neurologique incompatible : la fonction concernée est indisponible ; un atelier Shaediri, un technicien compétent ou une technique d’Ingénierie de transition peut adapter l’objet si son fonctionnement le permet."}],"lore":"Une technologie extraterrestre peut être physiquement présente sur Terre tout en restant conçue pour une autre morphologie, un autre système nerveux ou une autre logique d’interface.","compendium":"verite-catalogue-132-ergonomie-etrangere","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-cipherline-c-9', 'Cipherline C-9', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Communicateur personnel crypté à maillage adaptatif, format oreillette, brassard ou interface d’armure."},{"label":"Classification","value":"Communications · D"},{"label":"Réseau","value":"forme automatiquement un réseau local avec les unités autorisées et bascule entre radio, laser directionnel et relais disponibles"},{"label":"Authentification","value":"signatures matérielles et nanitiques ; les clés peuvent être révoquées à distance"},{"label":"Mode silencieux","value":"communications tactiles ou textuelles via interface compatible"},{"label":"Limites","value":"Ne permet pas une communication interstellaire instantanée sans infrastructure de relais appropriée."}],"lore":"Communicateur personnel crypté à maillage adaptatif, format oreillette, brassard ou interface d’armure.","compendium":"verite-catalogue-133-cipherline-c-9","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-omnispectre-os-6', 'Omnispectre OS-6', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Scanner multispectral portable utilisé en reconnaissance, maintenance et contrôle de cargaison."},{"label":"Classification","value":"Capteur · D"},{"label":"Capteurs","value":"thermique, ultraviolet, lidar, champ électromagnétique, spectrométrie simple, densité et mouvement"},{"label":"Analyse","value":"fournit des mesures précises exploitables par les compétences appropriées"},{"label":"Réseau","value":"peut partager ses données avec une armure ou un drone"},{"label":"Limites","value":"Ne reconnaît pas automatiquement une espèce, une technologie inconnue ou un phénomène surnaturel ; il fournit des données, pas l’expertise."}],"lore":"Scanner multispectral portable utilisé en reconnaissance, maintenance et contrôle de cargaison.","compendium":"verite-catalogue-134-omnispectre-os-6","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-handshake-iu-4', 'Handshake IU-4', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Pont matériel et logiciel destiné aux systèmes humains et aux normes alliées documentées."},{"label":"Classification","value":"Interface universelle · D"},{"label":"Adaptation","value":"reconfigure connectique, alimentation et protocole pour des interfaces connues ou proches"},{"label":"Isolement","value":"empêche un périphérique inconnu d’accéder directement au réseau personnel de l’agent"},{"label":"Traduction","value":"présente commandes et données dans une interface standard AIDH"},{"label":"Limites","value":"Ne pirate pas une authentification, ne déchiffre pas un protocole inconnu et ne rend pas compatible une technologie fondée sur un principe totalement étranger."}],"lore":"Pont matériel et logiciel destiné aux systèmes humains et aux normes alliées documentées.","compendium":"verite-catalogue-135-handshake-iu-4","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-mantis-field-tool', 'Mantis Field Tool', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Multitool de terrain à micro-usinage, soudure, découpe, diagnostic et manipulation fine."},{"label":"Classification","value":"Outil · D"},{"label":"Microfabrication","value":"peut produire des pièces simples à partir d’un stock de matière adapté"},{"label":"Réparation","value":"permet d’effectuer les opérations de maintenance prévues sans atelier lourd"},{"label":"Sécurité","value":"verrouillage des fonctions dangereuses selon l’habilitation"},{"label":"Limites","value":"N’est pas un atelier industriel et ne remplace ni composants rares ni compétence technique."}],"lore":"Multitool de terrain à micro-usinage, soudure, découpe, diagnostic et manipulation fine.","compendium":"verite-catalogue-136-mantis-field-tool","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-wisp-r-3', 'Wisp R-3', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Microdrone de reconnaissance silencieux, pliable dans un étui de ceinture."},{"label":"Classification","value":"Microdrone · D/O"},{"label":"Capteurs","value":"caméra, thermique, lidar, microphone directionnel et cartographie locale"},{"label":"Autonomie","value":"environ 4 heures de reconnaissance active"},{"label":"Contrôle","value":"peut suivre un itinéraire simple ou relayer les perceptions à l’opérateur"},{"label":"Limites","value":"Pas de PA gratuits : en combat, une manœuvre tactique significative du drone demande l’action ou l’interface normalement prévue par le système."}],"lore":"Microdrone de reconnaissance silencieux, pliable dans un étui de ceinture.","compendium":"verite-catalogue-137-wisp-r-3","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-nightjar-ew-5', 'Nightjar EW-5', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Brouilleur tactique intelligent capable de cibler des bandes, signatures et protocoles précis."},{"label":"Classification","value":"Guerre électronique · O"},{"label":"Brouillage sélectif","value":"coupe ou dégrade des transmissions connues sans saturer tout le spectre"},{"label":"Contre-brouillage","value":"cherche un chemin de communication alternatif et localise approximativement une source active"},{"label":"Isolement","value":"peut placer un petit réseau en mode fermé"},{"label":"Limites","value":"Aucun effet automatique sur télépathie, magie, Hologramme ou technologie qui n’utilise pas un support électromagnétique compatible."}],"lore":"Brouilleur tactique intelligent capable de cibler des bandes, signatures et protocoles précis.","compendium":"verite-catalogue-138-nightjar-ew-5","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-lattice-cell-lc-12', 'Lattice Cell LC-12', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Cellule énergétique compacte et reconfigurable, standard logistique AIDH."},{"label":"Classification","value":"Énergie · D/O"},{"label":"Universalité","value":"alimente la plupart des équipements AIDH portables via adaptation interne"},{"label":"Sécurité","value":"isolation automatique en cas de dommage local"},{"label":"Recharge","value":"nécessite un réseau AIDH ou un convertisseur lourd pour une recharge rapide"},{"label":"Limites","value":"Ne remplace pas les sources d’énergie exotiques d’un appareil incompatible."}],"lore":"Cellule énergétique compacte et reconfigurable, standard logistique AIDH.","compendium":"verite-catalogue-139-lattice-cell-lc-12","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-homecall-br-7', 'Homecall BR-7', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Balise de récupération militaire conçue pour survivre à un crash, une immersion ou un ensevelissement."},{"label":"Classification","value":"Balise · D/O"},{"label":"Rappel","value":"transmet identité, position et télémétrie médicale à un réseau AIDH accessible"},{"label":"Survie","value":"peut fonctionner plusieurs semaines en mode intermittent"},{"label":"Détresse","value":"dispose d’un mode de balise autonome impossible à désactiver sans accès physique ou autorisation supérieure"},{"label":"Limites","value":"Ce n’est pas une téléportation ; elle appelle une récupération si une force AIDH peut réellement intervenir."}],"lore":"Balise de récupération militaire conçue pour survivre à un crash, une immersion ou un ensevelissement.","compendium":"verite-catalogue-140-homecall-br-7","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-aegis-medpack-m-8', 'Aegis Medpack M-8', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Trousse médicale nanitique de campagne destinée à stabiliser et préparer un blessé pour des soins complets."},{"label":"Classification","value":"Médecine · D/O"},{"label":"Diagnostic","value":"cartographie lésions, toxines connues, oxygénation et constantes"},{"label":"Hémostase","value":"matériaux auto-expansifs et nanites médicales peuvent arrêter une hémorragie compatible"},{"label":"Support","value":"assistance respiratoire, perfusion et contrôle thermique compact"},{"label":"Limites","value":"N’accorde aucun soin gratuit ni aucune compétence. Les PV récupérés restent ceux obtenus par les règles de soins et les Talents réellement possédés."}],"lore":"Trousse médicale nanitique de campagne destinée à stabiliser et préparer un blessé pour des soins complets.","compendium":"verite-catalogue-141-aegis-medpack-m-8","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-farwalker-es-4', 'Farwalker ES-4', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Combinaison environnementale légère pour mondes hostiles, exploration et opérations de sauvetage."},{"label":"Classification","value":"Environnement · O"},{"label":"Profil","value":"Armure 2 contre dommages matériels ordinaires."},{"label":"Étanchéité","value":"gaz, immersion, poussières biologiques et contaminations atmosphériques"},{"label":"Réserve","value":"air et recyclage pour plusieurs heures selon effort"},{"label":"Thermorégulation","value":"supporte un large éventail de températures et pressions survivables"},{"label":"Limites","value":"Ne rend pas un Humain apte à vivre indéfiniment dans le vide, le plasma, des radiations massives ou une atmosphère chimiquement destructrice."}],"lore":"Combinaison environnementale légère pour mondes hostiles, exploration et opérations de sauvetage.","compendium":"verite-catalogue-142-farwalker-es-4","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-ghostbox-d-10', 'Ghostbox D-10', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Noyau de données blindé, physiquement isolable et doté d’une authentification multiparti."},{"label":"Classification","value":"Données · D/O"},{"label":"Journal","value":"conserve un historique matériel des accès et modifications"},{"label":"Isolement","value":"peut être retiré d’un réseau et lu sur interface sécurisée"},{"label":"Effacement","value":"l’autodestruction cryptographique rend les données illisibles sans détruire nécessairement le support"},{"label":"Limites","value":"N’est pas invariant face à l’Hologramme : pour cela, utiliser le matériel TUC Mnemosyne/Chaîne invariante."}],"lore":"Noyau de données blindé, physiquement isolable et doté d’une authentification multiparti.","compendium":"verite-catalogue-143-ghostbox-d-10","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-forgelet-f-2', 'Forgelet F-2', NULL, '{"nature":"objets","chapitre":"26","section":"Technologie AIDH générique","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Fabricateur de terrain pour consommables, pièces mécaniques et connectiques standard à partir d’un stock de matière."},{"label":"Classification","value":"Fabrication · O"},{"label":"Production","value":"munitions conventionnelles simples, pièces de rechange, joints, câbles, outils et structures légères"},{"label":"Bibliothèque","value":"modèles signés AIDH ; les plans sensibles demandent une autorisation"},{"label":"Temps","value":"de quelques minutes à plusieurs heures selon masse et précision"},{"label":"Limites","value":"Ne fabrique pas de matière exotique, de Calamitechnologie, de relique ni de composant dont le principe n’est pas présent dans sa bibliothèque."}],"lore":"Fabricateur de terrain pour consommables, pièces mécaniques et connectiques standard à partir d’un stock de matière.","compendium":"verite-catalogue-144-forgelet-f-2","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-defensor', 'Defensor', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Pistolet lourd semi-automatique à générateur de projectiles et extracteur de matière condensée. C’est l’arme de base emblématique de l’AIDH."},{"label":"Classification","value":"Arme de service · D"},{"label":"Profil","value":"DGT 14 · portée 50 m · Perforant 2 · semi-automatique · réserve ~1 000 tirs."},{"label":"Réserve de matière","value":"une cartouche-source alimente le générateur ; aucun rechargement conventionnel pendant une mission ordinaire"},{"label":"Verrou AIDH","value":"signature nanitique, biométrique ou autorisation temporaire"},{"label":"Fiabilité MT","value":"le premier enrayement purement mécanique du scénario peut être ignoré ; un échec narratif peut toujours produire une autre complication appropriée"}],"lore":"Pistolet lourd semi-automatique à générateur de projectiles et extracteur de matière condensée. C’est l’arme de base emblématique de l’AIDH.","compendium":"verite-catalogue-145-defensor","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-praetor-c-14', 'Praetor C-14', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Arme repliable conçue pour les opérations discrètes où le Defensor manque de volume de feu mais où un fusil long serait trop voyant."},{"label":"Classification","value":"Carabine compacte · O"},{"label":"Profil","value":"DGT 14 · portée 70 m · Automatique · Perforant 1 · réserve ~1 500 tirs."},{"label":"Repliable","value":"format sac/valise ; déploiement ou rangement 1 PA sous pression"},{"label":"Suppression","value":"compatible avec le Tir de suppression"},{"label":"Signature","value":"mécanique et thermique extrêmement faible pour une arme de cette puissance"}],"lore":"Arme repliable conçue pour les opérations discrètes où le Defensor manque de volume de feu mais où un fusil long serait trop voyant.","compendium":"verite-catalogue-146-praetor-c-14","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-custodian-ar-9', 'Custodian AR-9', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Fusil standard d’une unité AIDH sous atmosphère. Le générateur reconfigure le projectile plutôt que d’utiliser plusieurs types de chargeurs."},{"label":"Classification","value":"Fusil d’intervention · O"},{"label":"Profil","value":"Mode standard : DGT 16 · portée 100 m · Automatique · Perforant 2. Mode perforant : DGT 17 · portée 90 m · Perforant 3 · tir unique."},{"label":"Changement de régime","value":"1 PA ; le régime reste actif jusqu’à nouveau changement"},{"label":"Réserve","value":"environ 2 000 tirs standard ; le mode perforant consomme davantage de matière"},{"label":"Suppression","value":"uniquement en mode standard"},{"label":"Limites","value":"Le mode perforant n’ajoute pas une seconde Altération."}],"lore":"Fusil standard d’une unité AIDH sous atmosphère. Le générateur reconfigure le projectile plutôt que d’utiliser plusieurs types de chargeurs.","compendium":"verite-catalogue-147-custodian-ar-9","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-long-watch-sr-6', 'Long Watch SR-6', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Sniper moderne AIDH pensé pour neutraliser des cibles blindées ou augmentées à très grande distance."},{"label":"Classification","value":"Fusil de précision · L"},{"label":"Profil","value":"DGT 18 · portée 400 m · Perforant 3 · réserve 100 tirs spécialisés."},{"label":"Optique MT","value":"thermique, lidar, mouvement, compensation atmosphérique et télémétrie"},{"label":"Signature de cible","value":"peut mémoriser un profil technologique ou biométrique déjà acquis pour faciliter le suivi instrumental"},{"label":"Silence","value":"le projectile peut être généré en régime subsonique : DGT 16, portée 250 m, signature acoustique fortement réduite"},{"label":"Limites","value":"L’optique standard ne voit pas la Vérité d’une cible V ; utiliser IRIS-0 ou un dispositif TUC compatible."}],"lore":"Sniper moderne AIDH pensé pour neutraliser des cibles blindées ou augmentées à très grande distance.","compendium":"verite-catalogue-148-long-watch-sr-6","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-cerberus-hmg-3', 'Cerberus HMG-3', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Mitrailleuse lourde individuelle pour exoarmure ou affût, héritière de modèles AIDH plus anciens déjà capables d’emporter des milliers de projectiles."},{"label":"Classification","value":"Gatling · L"},{"label":"Profil","value":"DGT 17 · portée 120 m · Automatique lourd · Perforant 2 · réserve ~10 000 tirs."},{"label":"Saturation","value":"le Tir de suppression peut couvrir une zone ou un axe particulièrement large selon la fiction"},{"label":"Alimentation","value":"cartouche-source et cellule dédiée"},{"label":"Harnais","value":"un Homo Superior en Urgent Matter ou un porteur de Bastion peut l’utiliser comme arme individuelle"},{"label":"Limites","value":"Sans servomotricité, affût ou Vigueur exceptionnelle, son utilisation mobile est au minimum défavorable et peut être impossible selon la scène."}],"lore":"Mitrailleuse lourde individuelle pour exoarmure ou affût, héritière de modèles AIDH plus anciens déjà capables d’emporter des milliers de projectiles.","compendium":"verite-catalogue-149-cerberus-hmg-3","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-helios-pr-8', 'Helios PR-8', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Arme énergétique lourde humaine MT, plus compacte et plus stable que la plupart des modèles xénos importés sur Terre."},{"label":"Classification","value":"Fusil plasma · L"},{"label":"Profil","value":"DGT 18 · portée 100 m · Incendiaire · Perforant 2."},{"label":"Plasma","value":"une Altération appropriée peut choisir Enflammé"},{"label":"Surchauffe","value":"après Tir de suppression ou usage intensif, le système doit refroidir jusqu’à la prochaine activation avant de pouvoir recommencer un usage intensif"},{"label":"Cellule","value":"charge énergétique scellée ; pas de réserve de projectiles"}],"lore":"Arme énergétique lourde humaine MT, plus compacte et plus stable que la plupart des modèles xénos importés sur Terre.","compendium":"verite-catalogue-150-helios-pr-8","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-prometheus-px-2', 'Prometheus PX-2', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Projecteur de plasma à courte portée destiné aux cibles massives, essaims biologiques et fortifications."},{"label":"Classification","value":"Projecteur plasma · L"},{"label":"Profil","value":"DGT 17 · portée 25 m · Zone conique · Incendiaire · Surchauffe."},{"label":"Cône","value":"les cibles dans la zone se défendent selon les règles normales des attaques de zone"},{"label":"Brèche thermique","value":"une Altération peut viser une protection ou un support matériel approprié"},{"label":"Limites","value":"Peu discret, dangereux en environnement confiné et inutilisable comme outil de précision."}],"lore":"Projecteur de plasma à courte portée destiné aux cibles massives, essaims biologiques et fortifications.","compendium":"verite-catalogue-151-prometheus-px-2","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-null-lance-ie-4', 'Null Lance IE-4', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Arme de neutralisation technologique destinée aux drones, armures, augmentations exposées et véhicules légers."},{"label":"Classification","value":"Fusil ionique / EMP · L"},{"label":"Profil","value":"DGT 14 · portée 90 m · EMP · Perforant 1."},{"label":"Perturbation","value":"si l’attaque produit une Altération contre une cible technologique, elle peut viser capteurs, mobilité, arme embarquée ou interface exposée"},{"label":"Mode faible","value":"peut réduire DGT à 8 pour limiter les dégâts matériels tout en conservant EMP"},{"label":"Limites","value":"Aucun effet spécial sur magie, possession, pouvoir biologique ou technologie explicitement blindée contre ce vecteur sans réussir l’attaque normalement."}],"lore":"Arme de neutralisation technologique destinée aux drones, armures, augmentations exposées et véhicules légers.","compendium":"verite-catalogue-152-null-lance-ie-4","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-judicator-rl-5', 'Judicator RL-5', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Lanceur lourd à guidage inertiel et correction terminale, destiné aux véhicules, fortifications et grandes créatures matérielles."},{"label":"Classification","value":"Lance-roquette · L"},{"label":"Profil","value":"DGT 20 · portée 180 m · Zone 5 m · Perforant 3."},{"label":"Guidage","value":"peut recevoir une désignation de cible depuis un drone ou capteur AIDH ayant une ligne de données valide"},{"label":"Ogive","value":"explosive/kinétique standard ; les variantes spécialisées sont des dotations distinctes"},{"label":"Limites","value":"Arme de mission lourde ; pas de dotation personnelle ordinaire."}],"lore":"Lanceur lourd à guidage inertiel et correction terminale, destiné aux véhicules, fortifications et grandes créatures matérielles.","compendium":"verite-catalogue-153-judicator-rl-5","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-blackstar-gr-1', 'Blackstar GR-1', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Ogive expérimentale exploitant une masse exotique confinée pour créer une anomalie gravitationnelle très brève à l’impact."},{"label":"Classification","value":"Roquette matière noire · X"},{"label":"Profil","value":"DGT 18 · portée 150 m · Zone 4 m · Perforant 2."},{"label":"Anomalie","value":"après les dégâts, les cibles matérielles significatives dans la zone testent Vigueur + Athlétisme difficulté 18 ; échec : Altération appropriée de projection vers le centre, renversement, immobilisation sous surcharge ou arrachement d’équipement"},{"label":"Cibles massives","value":"sur véhicule ou structure, l’Altération peut viser stabilité ou mobilité plutôt qu’un déplacement impossible"},{"label":"Confinement","value":"chaque ogive est suivie et stockée comme matériel stratégique"},{"label":"Limites","value":"Ne crée pas de trou noir persistant, n’ignore pas automatiquement Armure ou Défense et n’affecte pas une entité immatérielle sans autre moyen de l’ancrer."}],"lore":"Ogive expérimentale exploitant une masse exotique confinée pour créer une anomalie gravitationnelle très brève à l’impact.","compendium":"verite-catalogue-154-blackstar-gr-1","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-ward-m-6', 'Ward M-6', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Couteau de service et de brèche utilisant un fil de coupe entretenu par champ."},{"label":"Classification","value":"Lame mono-moléculaire · O"},{"label":"Profil","value":"DGT 6 · Perforant 3."},{"label":"Outil","value":"coupe câbles, composites et panneaux légers rapidement"},{"label":"Sécurité","value":"le champ se coupe hors prise autorisée"},{"label":"Limites","value":"Perforant reste matériel : aucune interaction automatique avec une protection surnaturelle ou une cible immatérielle."}],"lore":"Couteau de service et de brèche utilisant un fil de coupe entretenu par champ.","compendium":"verite-catalogue-155-ward-m-6","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-breacher-b-9', 'Breacher B-9', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Lame lourde assistée utilisée par les unités blindées pour ouvrir une structure ou finir une cible au contact."},{"label":"Classification","value":"Lame d’assaut · L"},{"label":"Profil","value":"DGT 9 · Perforant 3."},{"label":"Servomotricité","value":"le profil complet suppose un porteur en armure assistée ou suffisamment puissant"},{"label":"Brèche","value":"une Altération appropriée peut créer une ouverture exploitable dans une protection matérielle"},{"label":"Limites","value":"N’ajoute pas de PA et n’autorise pas une attaque supplémentaire."}],"lore":"Lame lourde assistée utilisée par les unités blindées pour ouvrir une structure ou finir une cible au contact.","compendium":"verite-catalogue-156-breacher-b-9","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-second-skin', 'Second Skin', NULL, '{"nature":"objets","chapitre":"26","section":"Armures AIDH","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Sous-combinaison nanofibrée destinée aux agents qui doivent conserver une apparence civile."},{"label":"Classification","value":"Armure discrète · D"},{"label":"Profil","value":"Armure 4."},{"label":"Discrétion","value":"se porte sous une tenue ordinaire sans malus intrinsèque"},{"label":"Étanchéité partielle","value":"protège brièvement des gaz, projections biologiques et environnement contaminé"},{"label":"Auto-colmatage","value":"ferme une perforation mineure de la combinaison ; cela ne soigne pas le porteur"}],"lore":"Sous-combinaison nanofibrée destinée aux agents qui doivent conserver une apparence civile.","compendium":"verite-catalogue-157-second-skin","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-vesper-recon', 'Vesper Recon', NULL, '{"nature":"objets","chapitre":"26","section":"Armures AIDH","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Armure intermédiaire à faible signature, destinée à l’observation, infiltration et désignation de cible."},{"label":"Classification","value":"Armure de reconnaissance · O"},{"label":"Profil","value":"Armure 5."},{"label":"Occultation active","value":"1 PA ; jusqu’à action offensive ou mouvement brutal, l’utilisateur bénéficie d’une circonstance favorable +3 pour se dissimuler face aux capteurs visuels/thermiques ordinaires si l’environnement offre un minimum de contraste à exploiter"},{"label":"Capteurs","value":"Omnispectre intégré et liaison Wisp"},{"label":"Silence","value":"articulations et refroidissement optimisés"},{"label":"Limites","value":"La circonstance favorable ne trompe pas automatiquement une perception surnaturelle."}],"lore":"Armure intermédiaire à faible signature, destinée à l’observation, infiltration et désignation de cible.","compendium":"verite-catalogue-158-vesper-recon","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-urgent-matter', 'Urgent Matter', NULL, '{"nature":"objets","chapitre":"26","section":"Armures AIDH","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Armure de combat lourde emblématique de l’AIDH. Casque, plastron, membres, gants et bottes forment un ensemble hermétique et servomotorisé."},{"label":"Classification","value":"Armure lourde foldable · O"},{"label":"Profil","value":"Armure 8."},{"label":"Foldable","value":"hors combat, l’ensemble se replie en valise/sac spécialisé ; déploiement complet : 2 PA sous pression"},{"label":"Mobilité","value":"aucun malus intrinsèque de Furtivité ou d’Agilité simplement parce que l’armure est lourde"},{"label":"Environnement","value":"hermétique, air autonome, filtres, isolation thermique et protection aux contaminations ordinaires"},{"label":"Réseau","value":"liaison native aux armes, capteurs et modules TUC AIDH"},{"label":"Limites","value":"Armure 8 ne protège pas automatiquement contre un effet mental, spirituel, une Corruption ou une attaque ignorant explicitement la matière."}],"lore":"Armure de combat lourde emblématique de l’AIDH. Casque, plastron, membres, gants et bottes forment un ensemble hermétique et servomotorisé.","compendium":"verite-catalogue-159-urgent-matter","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-bastion', 'Bastion', NULL, '{"nature":"objets","chapitre":"26","section":"Armures AIDH","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Exoarmure d’assaut destinée aux opérations militaires lourdes et aux ennemis dépassant l’échelle humaine ordinaire."},{"label":"Classification","value":"Exoarmure d’assaut · L"},{"label":"Profil","value":"Armure 10."},{"label":"Servomusculature","value":"permet l’usage mobile normal de Cerberus, Judicator et autres armes lourdes prévues pour la plateforme"},{"label":"Verrou inertiel","value":"peut ancrer mécaniquement l’armure au sol ou à une structure préparée"},{"label":"Support","value":"capteurs, air, refroidissement et alimentation lourde intégrés"},{"label":"Limites","value":"Très visible, encombrante et réservée aux opérations ouvertes. Elle ne donne pas un bonus générique de Vigueur : elle permet les efforts explicitement supportés par sa servomécanique."}],"lore":"Exoarmure d’assaut destinée aux opérations militaires lourdes et aux ennemis dépassant l’échelle humaine ordinaire.","compendium":"verite-catalogue-160-bastion","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-argus-t', 'ARGUS-T', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Scanner/visière nécessaire à Calibration de cohérence et aux diagnostics locaux de l’Hologramme."},{"label":"Classification","value":"Capteur de cohérence · S"},{"label":"Lecture brute","value":"repère incohérences simultanées entre capteurs, ruptures de conservation, stress local du Voile et stabilisation artificielle"},{"label":"Avec Talent","value":"Calibration de cohérence peut déterminer le type général de sollicitation : fonctionnement normal, Révélation récente/en cours, contrainte sur le Voile ou anomalie de cohérence"},{"label":"Réseau","value":"peut partager ses mesures avec Mnemosyne ou CLEARSKY"},{"label":"Limites","value":"Ne montre pas la forme réelle d’une cible V, ne donne pas son espèce et ne Révèle personne."}],"lore":"Scanner/visière nécessaire à Calibration de cohérence et aux diagnostics locaux de l’Hologramme.","compendium":"verite-catalogue-161-argus-t","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-mnemosyne', 'Mnemosyne', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Caméra/noyau de données technomagique conçu pour résister aux corrections ordinaires postérieures de l’Hologramme."},{"label":"Classification","value":"Enregistreur invariant · S"},{"label":"Invariant","value":"les données réellement captées par ses propres capteurs ne sont pas automatiquement réécrites après coup"},{"label":"Chaîne","value":"avec le Talent Chaîne invariante, peut relier un flux externe et détecter toute modification ultérieure comme rupture d’intégrité"},{"label":"Scellé","value":"journal matériel des accès et copie chiffrée indépendante"},{"label":"Limites","value":"Il ne voit que ce que son capteur pouvait réellement percevoir. Une cible V non percée par une perception spéciale reste enregistrée sous sa traduction Hologramme."}],"lore":"Caméra/noyau de données technomagique conçu pour résister aux corrections ordinaires postérieures de l’Hologramme.","compendium":"verite-catalogue-162-mnemosyne","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-stator', 'STATOR', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Tripode, brassard ou module d’armure servant de référence de cohérence à une cible consentante."},{"label":"Classification","value":"Ancre de terrain · S"},{"label":"Ancrage","value":"avec le Talent Ancrage de terrain, l’opérateur peut opposer Esprit + Technologie à un effet cherchant à forcer un changement V/SR/R"},{"label":"Libre arbitre","value":"la cible peut toujours changer volontairement d’état"},{"label":"Portée","value":"courte ; le dispositif doit rester actif et relié à la cible"},{"label":"Limites","value":"Ne force pas une cible R à devenir V, ne Révèle personne et ne remplace pas une HDS."}],"lore":"Tripode, brassard ou module d’armure servant de référence de cohérence à une cible consentante.","compendium":"verite-catalogue-163-stator","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-clearsky', 'CLEARSKY', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Projecteur de mission qui crée une petite zone d’observation instrumentale stable."},{"label":"Classification","value":"Projecteur de cohérence · S"},{"label":"Fenêtre","value":"avec le Talent Fenêtre invariante : 2 PA, petite zone, jusqu’à la fin du round suivant ; les phénomènes réellement observés ne sont pas immédiatement réinterprétés dans les données reliées"},{"label":"Transmission","value":"peut transférer les données vers Mnemosyne/Chaîne invariante"},{"label":"Déploiement","value":"format caisse ou sac lourd ; installation rapide sur trépied"},{"label":"Limites","value":"N’éteint pas l’Hologramme, ne montre pas la Vérité d’une cible V et ne change aucun état V/SR/R."}],"lore":"Projecteur de mission qui crée une petite zone d’observation instrumentale stable.","compendium":"verite-catalogue-164-clearsky","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-iris-0', 'IRIS-0', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Optique institutionnelle rare permettant d’observer localement ce que l’Hologramme est en train de traduire."},{"label":"Classification","value":"Optique de Vérité · S/X"},{"label":"Vision de Vérité","value":"dans son champ et à portée opérationnelle, peut montrer la morphologie réelle d’une cible V/SR/R si aucun dispositif de suppression spécialisé ne l’en empêche"},{"label":"Non-révélation","value":"la cible reste dans son état : V reste V, avec ses caractéristiques et Talents de V"},{"label":"Enregistrement","value":"couplée à Mnemosyne, peut conserver la représentation réellement observée"},{"label":"Limites","value":"N’identifie ni espèce, nom, Sang, Talent, intention ou faiblesse. Une HDS/Holojamer ou une protection anti-Holo peut opposer ou neutraliser la lecture selon sa règle propre."}],"lore":"Optique institutionnelle rare permettant d’observer localement ce que l’Hologramme est en train de traduire.","compendium":"verite-catalogue-165-iris-0","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-triad-r', 'TRIAD-R', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Réseau de trois microcapteurs à placer autour d’une zone sensible."},{"label":"Classification","value":"Triangulateur de Révélation · S"},{"label":"Déclenchement","value":"une Révélation ou transition de Vérité réellement détectable dans le volume produit une alerte"},{"label":"Données","value":"horodatage, secteur/direction générale et intensité de perturbation"},{"label":"Discrétion","value":"capteurs de la taille d’une pièce ou d’un petit galet"},{"label":"Limites","value":"Ne dit pas automatiquement qui s’est Révélé, quelle espèce est impliquée ni où se trouve la cible après son déplacement."}],"lore":"Réseau de trois microcapteurs à placer autour d’une zone sensible.","compendium":"verite-catalogue-166-triad-r","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-twinkey', 'TwinKey', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Deux chaînes instrumentales physiquement différentes comparent en permanence leurs historiques."},{"label":"Classification","value":"Détecteur d’invariance · S"},{"label":"Alerte","value":"si les deux historiques deviennent causalement incompatibles, le système signale qu’une correction ou rupture d’intégrité a eu lieu"},{"label":"Forensique","value":"conserve les divergences et leurs horodatages"},{"label":"Indépendance","value":"fonctionne même sans utilisateur Révélé"},{"label":"Limites","value":"Détecte une contradiction ; il ne reconstruit pas automatiquement la version vraie ni la cause de la réécriture."}],"lore":"Deux chaînes instrumentales physiquement différentes comparent en permanence leurs historiques.","compendium":"verite-catalogue-167-twinkey","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-q-lock', 'Q-Lock', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Périmètre d’enregistrement et de contrôle destiné à une scène contaminée ou un laboratoire temporaire."},{"label":"Classification","value":"Balise de quarantaine · S"},{"label":"Périmètre","value":"enregistre entrées/sorties physiques, communications autorisées et ruptures majeures de cohérence"},{"label":"Isolation","value":"peut couper les émissions réseau non autorisées dans une petite zone"},{"label":"Journal","value":"copie vers Ghostbox/Mnemosyne selon niveau de sensibilité"},{"label":"Limites","value":"Ce n’est ni une prison ni une barrière surnaturelle. Une créature peut sortir physiquement si rien ne l’en empêche ; elle laisse simplement beaucoup plus de traces."}],"lore":"Périmètre d’enregistrement et de contrôle destiné à une scène contaminée ou un laboratoire temporaire.","compendium":"verite-catalogue-168-q-lock","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-needle-t', 'Needle-T', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Drone jetable de reconnaissance pour zones où l’AIDH ne veut pas engager immédiatement un agent."},{"label":"Classification","value":"Sonde Vérité · S"},{"label":"Charge utile","value":"ARGUS-T simplifié, lidar, chimique, biologique, radiologique, thermique et Mnemosyne miniature"},{"label":"Mission","value":"cartographie, prélèvements, observation et transmission"},{"label":"Perte","value":"prévue pour être sacrifiable ; l’autodestruction détruit le noyau de données si une capture est détectée"},{"label":"Limites","value":"Ses capteurs ont exactement les mêmes limites conceptuelles que leurs versions portables : pas d’identification magique universelle."}],"lore":"Drone jetable de reconnaissance pour zones où l’AIDH ne veut pas engager immédiatement un agent.","compendium":"verite-catalogue-169-needle-t","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-janus-b', 'JANUS-B', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Module de terrain permettant à un capteur, outil ou contenant prévu à cet effet d’interagir avec une manifestation immatérielle réellement présente."},{"label":"Classification","value":"Projecteur biphysique · S"},{"label":"Couplage","value":"rend le dispositif porteur biphysique pendant une scène ou jusqu’à coupure"},{"label":"Usage","value":"prélèvement, fermeture de contenant, manipulation d’objet spirituel ou mesure locale"},{"label":"Modularité","value":"existe en version pince, caméra, cadre de porte ou accessoire d’arme non létal"},{"label":"Limites","value":"Ne détecte pas automatiquement l’immatériel et ne rend pas toutes les attaques du porteur capables de toucher n’importe quelle âme ou entité."}],"lore":"Module de terrain permettant à un capteur, outil ou contenant prévu à cet effet d’interagir avec une manifestation immatérielle réellement présente.","compendium":"verite-catalogue-170-janus-b","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-ark-6', 'ARK-6', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Conteneur blindé destiné aux tissus de Vérité, reliques, fragments de Fléau, objets xénos instables ou petits organismes inconnus."},{"label":"Classification","value":"Cage de cohérence · S"},{"label":"Isolement","value":"réseau, environnement, pression et alimentation indépendants"},{"label":"Biphysique","value":"version S peut recevoir un module JANUS pour contenir une manifestation partiellement immatérielle"},{"label":"Journal","value":"tous les changements internes sont enregistrés sur une chaîne locale"},{"label":"Limites","value":"La cage n’annule pas les pouvoirs d’un artefact cosmique ou d’une entité majeure. Elle fournit un confinement, pas une garantie métaphysique."}],"lore":"Conteneur blindé destiné aux tissus de Vérité, reliques, fragments de Fléau, objets xénos instables ou petits organismes inconnus.","compendium":"verite-catalogue-171-ark-6","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-sentinel-n', 'SENTINEL-N', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Surveillance continue du profil neural et nanitique d’un agent AIDH."},{"label":"Classification","value":"Module anti-possession · S"},{"label":"Alerte","value":"détecte une rupture brutale et étrangère dans les schémas neurologiques, moteurs ou d’authentification"},{"label":"Verrouillage","value":"peut révoquer automatiquement l’accès aux armes stratégiques, réseaux et véhicules sensibles"},{"label":"Témoin","value":"transmet l’incident à l’escouade et au contrôle local"},{"label":"Limites","value":"Ne donne aucune immunité à la possession, domination ou attaque mentale. Il limite surtout ce qu’un intrus gagne en contrôlant le corps."}],"lore":"Surveillance continue du profil neural et nanitique d’un agent AIDH.","compendium":"verite-catalogue-172-sentinel-n","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-wake-3', 'WAKE-3', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Dispositif médical d’urgence provoquant une réinitialisation neurochimique et nanitique extrêmement brutale."},{"label":"Classification","value":"Injecteur de rupture neuro · S"},{"label":"Déclenchement","value":"1 PA au contact sur soi ou cible consentante/immobilisée"},{"label":"Tentative","value":"autorise un nouveau test approprié contre un contrôle technologique ou neurologique directement dépendant de l’activité cérébrale ; le second résultat est définitif"},{"label":"Contrecoup","value":"la cible devient Tendu et subit une incapacité brève appropriée jusqu’à la fin de sa prochaine activation"},{"label":"Limites","value":"Aucun effet automatique sur pacte, malédiction, possession spirituelle ou pouvoir dont le mécanisme ne dépend pas du système nerveux."}],"lore":"Dispositif médical d’urgence provoquant une réinitialisation neurochimique et nanitique extrêmement brutale.","compendium":"verite-catalogue-173-wake-3","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-hds-4-veil-lock', 'HDS-4 Veil Lock', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Dispositif AIDH de contrainte sur la cohérence Hologramme, utilisé pour empêcher une cible encore Voilée de progresser vers SR/R."},{"label":"Classification","value":"Holojamer / suppression · S/X"},{"label":"Maintien V","value":"sur une cible V dans la zone, une tentative de passage vers SR/R rencontre l’opposition définie par le dispositif/opérateur ; en cas d’échec, la transition n’a pas lieu"},{"label":"Conséquence","value":"les pouvoirs exigeant SR/R restent indisponibles tant que la cible est maintenue V"},{"label":"Zone","value":"versions portables très limitées ; versions installation peuvent couvrir une pièce ou cellule"},{"label":"Limites","value":"il n’existe pas de procédure universelle permettant de forcer une cible déjà R à revenir en V. Le dispositif ne Révèle personne d’autre et ne constitue pas une vision de Vérité."}],"lore":"Dispositif AIDH de contrainte sur la cohérence Hologramme, utilisé pour empêcher une cible encore Voilée de progresser vers SR/R.","compendium":"verite-catalogue-174-hds-4-veil-lock","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-caliban-s', 'CALIBAN-S', NULL, '{"nature":"objets","chapitre":"26","section":"Dispositifs spécifiques à Terra Umbra","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH","Terra Umbra"],"proprietes":[{"label":"Description","value":"Spectromètre spécialisé destiné aux objets, tissus et sites déjà suspectés d’avoir été exposés à une Source de Fléau ou à une Calamitechnologie."},{"label":"Classification","value":"Analyseur de souillure matérielle · S"},{"label":"Échantillon","value":"détermine si le prélèvement présente une anomalie stable incompatible avec les signatures technologiques/biologiques normales connues"},{"label":"Calibration","value":"avec une signature de référence déjà documentée, peut dire si l’échantillon est compatible avec la même famille de contamination"},{"label":"Quarantaine","value":"interface directement avec ARK-6 et Q-Lock"},{"label":"Limites","value":"Ne lit pas la jauge de Corruption d’un personnage, ne nomme pas automatiquement le Fléau et ne remplace pas un test de résistance ou une expertise occulte."}],"lore":"Spectromètre spécialisé destiné aux objets, tissus et sites déjà suspectés d’avoir été exposés à une Source de Fléau ou à une Calamitechnologie.","compendium":"verite-catalogue-175-caliban-s","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-calamitechnologie', 'Calamitechnologie', NULL, '{"nature":"objets","chapitre":"26","section":"Matériel hors dotation normale","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Technologie exploitant directement un principe de Fléau. L’AIDH la considère potentiellement plus dangereuse encore que la Magitech."},{"label":"Classification","value":"Programme interdit / expérimental · X"},{"label":"Statut","value":"Armée 0, programme noir, laboratoire dissident ou objet capturé"},{"label":"Confinement","value":"les prototypes relèvent des règles d’équipement corrompu et de Souillure"},{"label":"Doctrine","value":"aucune pièce de Calamitechnologie n’est une simple variante du catalogue militaire"},{"label":"Limites","value":"jamais une dotation de routine. Les modèles précis sont décrits dans le chapitre consacré aux Fléaux."}],"lore":"Technologie exploitant directement un principe de Fléau. L’AIDH la considère potentiellement plus dangereuse encore que la Magitech.","compendium":"verite-catalogue-176-calamitechnologie","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-26-dotation-et-acces-aidh', 'Dotation et accès AIDH', NULL, '{"nature":"objets","chapitre":"26","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":[],"proprietes":[{"label":"D","value":"Niveau: Dotation personnelle · Usage: Matériel courant d’un agent autorisé : Defensor, communicateur, kit médical, scanner."},{"label":"O","value":"Niveau: Opération · Usage: Équipement de mission : Urgent Matter, fusil d’intervention, drones, outils spécialisés."},{"label":"L","value":"Niveau: Lourd · Usage: Sniper, gatling, plasma, Bastion, lanceurs. Autorisation liée à une opération ouverte."},{"label":"S","value":"Niveau: Spécial TUC · Usage: Cohérence, Hologramme, enregistrement invariant, confinement surnaturel."},{"label":"X","value":"Niveau: Expérimental / stratégique · Usage: Blackstar, prototypes Armée 0, HDS lourde, Calamitechnologie. Objet de scénario ou autorisation exceptionnelle."}],"lore":"La dotation AIDH suit le mandat opérationnel : certaines pièces sont personnelles, d’autres n’existent qu’avec une mission ouverte ou une autorisation stratégique.","compendium":"verite-catalogue-177-dotation-et-acces-aidh","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-27-croc-de-la-faim', 'Croc de la Faim', NULL, '{"nature":"objets","chapitre":"27","section":"Vhodhal — Dévoration","statut_catalogue":"catalogue","origine":"catalogue","tags":["Corrompu","Calamitechnologie"],"proprietes":[{"label":"Nature","value":"Relique Vhodhal • Profil: DGT 4 • Mêlée • Propriété: Après au moins 1 PV réel, le porteur peut réveiller la lame : la cible subit Corruptif 15 Vhodhal, physique, une fois par scène."},{"label":"Souillure / risque","value":"Souillure 15 au premier réveil de la scène."}],"lore":null,"compendium":"verite-catalogue-178-croc-de-la-faim","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
