INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-27-coffre-d-etat-thu-2', 'Coffre d’État THU-2', NULL, '{"nature":"objets","chapitre":"27","section":"Thul — Fixation","statut_catalogue":"catalogue","origine":"catalogue","tags":["Corrompu","Calamitechnologie"],"proprietes":[{"label":"Nature","value":"Calamitechnologie • Profil: Conteneur • Propriété: Tout ce qui est scellé reste pratiquement dans son état physique actuel. Sceller ou rompre le champ est l’activation ; le coffre peut être détruit."},{"label":"Souillure / risque","value":"Souillure 15."}],"lore":null,"compendium":"verite-catalogue-215-coffre-d-etat-thu-2","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-27-boite-noire-abyssale-thu-4', 'Boîte noire Abyssale THU-4', NULL, '{"nature":"objets","chapitre":"27","section":"Thul — Fixation","statut_catalogue":"catalogue","origine":"catalogue","tags":["Corrompu","Calamitechnologie"],"proprietes":[{"label":"Nature","value":"Calamitechnologie • Profil: Enregistrement invariant • Propriété: Fixe l’état de données enregistrées contre corrections ordinaires de l’Hologramme et altérations diffuses. Ne voit pas ce que le capteur n’a jamais enregistré et reste piratable/destructible."},{"label":"Souillure / risque","value":"Souillure 18 à la fixation."}],"lore":null,"compendium":"verite-catalogue-216-boite-noire-abyssale-thu-4","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-27-projecteur-chronostatique-thu-7', 'Projecteur Chronostatique THU-7', NULL, '{"nature":"objets","chapitre":"27","section":"Thul — Fixation","statut_catalogue":"catalogue","origine":"catalogue","tags":["Corrompu","Calamitechnologie"],"proprietes":[{"label":"Nature","value":"Calamitechnologie lourde • Profil: 2 PA • 20 m • Propriété: Désigne un processus continu identifié : feu, corrosion, moteur, régénération, transformation, croissance. Si surnaturel : Volonté + Maîtrise spirituelle contre Puissance. En réussite le processus est figé jusqu’à fin de la prochaine activation de sa Source."},{"label":"Souillure / risque","value":"Souillure 21 • INSTABLE."}],"lore":null,"compendium":"verite-catalogue-217-projecteur-chronostatique-thu-7","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-27-grenade-d-inertie-thu-9', 'Grenade d’Inertie THU-9', NULL, '{"nature":"objets","chapitre":"27","section":"Thul — Fixation","statut_catalogue":"catalogue","origine":"catalogue","tags":["Corrompu","Calamitechnologie"],"proprietes":[{"label":"Nature","value":"Calamitechnologie stratégique • Profil: Zone 4 m • 1 round • Propriété: Toute capacité surnaturelle de métamorphose, dématérialisation, régénération ou changement instantané de support doit d’abord vaincre Puissance 18 de la grenade puis se résoudre normalement."},{"label":"Souillure / risque","value":"Souillure 21 à l’armement • INSTABLE."}],"lore":null,"compendium":"verite-catalogue-218-grenade-d-inertie-thu-9","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-27-grande-orbe', 'Grande Orbe', NULL, '{"nature":"objets","chapitre":"27","section":"Artefacts cosmiques et reliques canoniques","statut_catalogue":"unique","origine":"artifact","tags":["Artefact unique"],"proprietes":[{"label":"Source","value":"Sharith"},{"label":"Statut","value":"Fragment physique de Sharith utilisé par Bellatheis pour détecter les ascendances compatibles. Unique / scénario."}],"lore":"Fragment physique de Sharith utilisé par Bellatheis pour détecter les ascendances compatibles. Unique / scénario.","compendium":"verite-catalogue-219-grande-orbe","mj":true}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-27-nacres-noires', 'Nacres noires', NULL, '{"nature":"objets","chapitre":"27","section":"Artefacts cosmiques et reliques canoniques","statut_catalogue":"unique","origine":"artifact","tags":["Artefact unique"],"proprietes":[{"label":"Source","value":"Vhadhi"},{"label":"Statut","value":"Les premières étaient des yeux d’Abominations ; composants majeurs et rares de Métastasismancie."}],"lore":"Les premières étaient des yeux d’Abominations ; composants majeurs et rares de Métastasismancie.","compendium":"verite-catalogue-220-nacres-noires","mj":true}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-27-nahfr', 'Nahfr', NULL, '{"nature":"objets","chapitre":"27","section":"Artefacts cosmiques et reliques canoniques","statut_catalogue":"unique","origine":"artifact","tags":["Artefact unique"],"proprietes":[{"label":"Source","value":"Shaoggith"},{"label":"Statut","value":"Peau de Tiamat/Shaoggith portée comme armure occulte. Artefact cosmique unique ; aucun prix normal."}],"lore":"Peau de Tiamat/Shaoggith portée comme armure occulte. Artefact cosmique unique ; aucun prix normal.","compendium":"verite-catalogue-221-nahfr","mj":true}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-27-mue-de-rulfam', 'Mue de Rulfam', NULL, '{"nature":"objets","chapitre":"27","section":"Artefacts cosmiques et reliques canoniques","statut_catalogue":"unique","origine":"artifact","tags":["Artefact unique"],"proprietes":[{"label":"Source","value":"Shaoggith"},{"label":"Statut","value":"Relique majeure capable de transformer profondément un porteur lié à Shaoggith. Source de Corruption exceptionnelle."}],"lore":"Relique majeure capable de transformer profondément un porteur lié à Shaoggith. Source de Corruption exceptionnelle.","compendium":"verite-catalogue-222-mue-de-rulfam","mj":true}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-27-lance-de-longinus', 'Lance de Longinus', NULL, '{"nature":"objets","chapitre":"27","section":"Artefacts cosmiques et reliques canoniques","statut_catalogue":"unique","origine":"artifact","tags":["Artefact unique"],"proprietes":[{"label":"Source","value":"V’Aagor ?"},{"label":"Statut","value":"Relique revendiquée par l’Ordre. Sa nature exacte reste volontairement ouverte ; aucun profil V1 arbitraire."}],"lore":"Relique revendiquée par l’Ordre. Sa nature exacte reste volontairement ouverte ; aucun profil V1 arbitraire.","compendium":"verite-catalogue-223-lance-de-longinus","mj":true}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-24-marche-de-verite-des-exiles-acces-et-rarete', 'Marché de Vérité des Exilés — accès et rareté', NULL, '{"nature":"objets","chapitre":"24","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":["Exilés","Marché de Vérité"],"proprietes":[{"label":"Jadecenters / Palameta","value":"marché noir magique orco-gobelin, intermédiaires, revente, matériel volé, protections, composants et commandes discrètes."},{"label":"Ateliers whurtens","value":"runes, supports préparés, réparation et objets stabilisés ; l’accès dépend davantage de la relation et de la tradition que d’une boutique publique."},{"label":"Réseaux azménoriens","value":"prototypes technomagiques modernes, souvent commandés pièce par pièce ; une partie circule via Pluton, des Silcenters ou le Syndicat de Jade."},{"label":"Loges et marchés occultes","value":"consommables, reliques mineures, composants de rites et objets issus de successions ou de saisies."},{"label":"V0 - courant","value":"Disponibilité: Composant, support, arme ordinaire adaptée · Ordre de prix terrestre: 100 à 2 000 $"},{"label":"V1 - spécialisé","value":"Disponibilité: Rune chargée, capteur occulte simple, arme préparée · Ordre de prix terrestre: 2 000 à 10 000 $"},{"label":"V2 - rare","value":"Disponibilité: Objet runique durable, technomagie portable · Ordre de prix terrestre: 10 000 à 50 000 $"},{"label":"V3 - prototype","value":"Disponibilité: Arsenal de Rupture, installations de contention · Ordre de prix terrestre: 50 000 à 150 000 $"},{"label":"V4 - exceptionnel","value":"Disponibilité: Prototype majeur, pièce antique, commande politiquement sensible · Ordre de prix terrestre: prix + dette + scénario"}],"lore":"Les Jadecenters, ateliers whurtens, réseaux azménoriens et loges occultes n’ouvrent pas tous les mêmes portes : l’accès dépend autant des relations que de l’argent.","compendium":"verite-catalogue-224-marche-de-verite-des-exiles-acces-et-rarete","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-25-marche-xeno-circuits-acces-et-dettes', 'Marché xéno — circuits, accès et dettes', NULL, '{"nature":"objets","chapitre":"25","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":["Xéno","Shaediri"],"proprietes":[{"label":"Shaediri","value":"marché de survie et de contrebande xéno à Los Demonos. Le réseau vend, adapte, répare et importe ; il fonctionne volontiers par points de crédit et dettes de service plutôt qu’en monnaie galactique."},{"label":"Feeshri","value":"filière de très haut niveau, reliée aux G-corporations et parfois aux Roesis. L’accès est politique, social et dangereux ; une grande partie de leur armement est psychique ou biométriquement verrouillée."},{"label":"Diasporas","value":"Mo’sens, Thalsios, Sérys et autres communautés possèdent leurs propres circuits, souvent plus faciles pour du matériel culturellement courant mais difficiles pour un Terrien non introduit."},{"label":"AIDH","value":"les modèles dépassés, perdus, volés ou déclassifiés peuvent finir sur le marché noir. Les technologies récentes et la Cohérence restent beaucoup plus difficiles à obtenir."},{"label":"M0 - ouvert","value":"Sens: Objet légal ou facilement détournable · Exemple: Cellule standard, arme à projectiles commune"},{"label":"M1 - xéno courant","value":"Sens: Marché Shaediri / diaspora · Exemple: Laser, ion, arme Trius commune"},{"label":"M2 - restreint","value":"Sens: Intermédiaire, réputation ou commande · Exemple: Plasma Sérys, mono-filament, matériel militaire"},{"label":"M3 - noir","value":"Sens: Importation interdite / haut risque · Exemple: Ad’rak, Xewen, AIDH ancien, Feeshri"},{"label":"M4 - exceptionnel","value":"Sens: Mission, dette majeure, commanditaire · Exemple: Pastille AIDH, arme Feeshri supérieure, G-corporation"},{"label":"1 PdC","value":"Service limité, livraison, information, faveur mineure"},{"label":"2 PdC","value":"Service risqué ou accès clandestin significatif"},{"label":"3 PdC","value":"Mission dangereuse, cargaison rare, engagement important"},{"label":"4+ PdC","value":"Dette structurante : extraction, prototype, importation fortement interdite"}],"lore":"Le marché xéno terrestre fonctionne par diasporas, contrebande et réputation ; chez les Shaediri, une dette ou un service peut valoir davantage qu’une somme en Dykal.","compendium":"verite-catalogue-225-marche-xeno-circuits-acces-et-dettes","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-26-conventions-techniques-aidh', 'Conventions techniques AIDH', NULL, '{"nature":"objets","chapitre":"26","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":["AIDH"],"proprietes":[{"label":"Verrouillé","value":"un matériel AIDH reconnaît normalement un utilisateur autorisé, une signature nanitique ou une habilitation temporaire. Le contourner demande une véritable intrusion technique ; voler l’objet ne suffit pas."},{"label":"Perforant X","value":"ignore X points d’Armure matérielle."},{"label":"EMP","value":"sur au moins 1 dégât réel à un système exposé, neutralise une fonction électronique appropriée jusqu’à la fin de la prochaine activation. Ne neutralise pas la magie, l’âme ou une biologie purement organique."},{"label":"Incendiaire","value":"sur une Altération appropriée, peut infliger Enflammé. Les armes plasma peuvent aussi posséder Surchauffe."},{"label":"Réserve de matière","value":"les générateurs modernes fabriquent leurs projectiles à partir d’une cartouche-source. La réserve indiquée est une autonomie pratique, pas un chargeur conventionnel."},{"label":"Intégration nanitique","value":"certaines interfaces deviennent particulièrement fluides avec un Homo Superior, mais une compatibilité AIDH ne crée jamais gratuitement un bonus de compétence."},{"label":"Hologramme","value":"aucun capteur générique AIDH ne voit automatiquement la Vérité d’une cible V. Il faut un appareil explicitement conçu pour cela."}],"lore":"L’équipement AIDH repose sur des verrous d’autorisation, des réserves de matière, des effets ioniques et une intégration nanitique qui n’ont rien d’un simple équivalent plus puissant du matériel terrestre.","compendium":"verite-catalogue-226-conventions-techniques-aidh","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-26-protocoles-de-coherence-compatibilite-materielle', 'Protocoles de Cohérence — compatibilité matérielle', NULL, '{"nature":"objets","chapitre":"26","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":["AIDH","Cohérence"],"proprietes":[{"label":"Calibration de cohérence","value":"Matériel: ARGUS-T · Rappel: Lecture du stress de l’Hologramme et des anomalies locales."},{"label":"Chaîne invariante","value":"Matériel: Mnemosyne / Ghostbox compatible · Rappel: Relie un flux et détecte les réécritures ultérieures."},{"label":"Ancrage de terrain","value":"Matériel: STATOR · Rappel: Opposition aux changements V/SR/R forcés sur une cible consentante."},{"label":"Fenêtre invariante","value":"Matériel: CLEARSKY + Mnemosyne · Rappel: Observation instrumentale stable temporaire ; aucune Révélation forcée."},{"label":"Voir sous le Voile","value":"Matériel: IRIS-0 · Rappel: Capacité matérielle rare : voir la traduction réelle sans changer l’état de la cible."},{"label":"Maintenir Voilé","value":"Matériel: HDS-4 · Rappel: Bloque la progression V→SR/R ; règle R→V non généralisée dans ce corpus."}],"lore":"Les protocoles de Cohérence ne sont pas des pouvoirs autonomes : ils reposent sur des appareils précis qui mesurent, ancrent ou conservent ce que l’Hologramme chercherait autrement à réinterpréter.","compendium":"verite-catalogue-227-protocoles-de-coherence-compatibilite-materielle","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-26-dotations-types-aidh', 'Dotations types AIDH', NULL, '{"nature":"objets","chapitre":"26","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":["AIDH"],"proprietes":[{"label":"Dotation","value":"Ces ensembles sont des exemples de briefing, pas des packs automatiques. La mission et le commandement peuvent retirer ou ajouter n''importe quelle pièce."},{"label":"Agent discret","value":"Defensor, Second Skin, Cipherline, Omnispectre, Handshake, Aegis Medpack."},{"label":"Intervention standard","value":"Defensor, Custodian AR-9, Urgent Matter, Wisp, Nightjar, Aegis Medpack."},{"label":"Reconnaissance TUC","value":"Defensor, Vesper Recon, ARGUS-T, Mnemosyne, TRIAD-R, Needle-T."},{"label":"Confinement surnaturel","value":"Urgent Matter, STATOR, ARK-6, JANUS-B, Q-Lock, SENTINEL-N."},{"label":"Assaut lourd","value":"Bastion, Cerberus ou Helios, Judicator, Wisp, Homecall."},{"label":"Cellule de Cohérence","value":"ARGUS-T, Mnemosyne, CLEARSKY, STATOR, IRIS-0 selon habilitation, HDS-4 selon mandat."}],"lore":"Une escouade AIDH n’emporte pas un inventaire fixe : son équipement reflète le mandat, la discrétion attendue et le niveau de menace identifié avant l’intervention.","compendium":"verite-catalogue-228-dotations-types-aidh","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'objets', 'verite-27-equipement-corrompu-et-calamitechnologie-principes', 'Équipement corrompu et Calamitechnologie — principes', NULL, '{"nature":"objets","chapitre":"27","section":"Référence","statut_catalogue":"reference","origine":"reference","tags":["Corruption","Calamitechnologie"],"proprietes":[{"label":"Objet souillé","value":"Définition: Objet ordinaire ayant absorbé accidentellement une Source. · Disponibilité: Trouvaille, marché noir, récupération."},{"label":"Relique de culte","value":"Définition: Objet conçu rituellement pour canaliser un Fléau. · Disponibilité: Culte, prise de guerre, marché occulte."},{"label":"Calamitechnologie","value":"Définition: Dispositif technologique utilisant un noyau de Source réel ou un phénomène équivalent. · Disponibilité: Prototype, laboratoire noir, scénario."},{"label":"Artefact cosmique","value":"Définition: Fragment majeur/unique d’une entité ou objet irremplaçable. · Disponibilité: Unique ; aucun prix normal."},{"label":"Règles communes","value":"Pas de DON gratuit. Un objet fournit uniquement les propriétés écrites sur sa fiche. Souillure. Un objet actif indique sa difficulté propre. Transporter un objet correctement confiné ne provoque pas de test ; activation, fuite ou manipulation dangereuse oui. Corruptif. Certains objets exposent aussi la cible. Par défaut, un même objet/vecteur ne provoque qu’une exposition par cible et par scène. INSTABLE. Sur échec narratif au Test de Souillure de l’utilisateur, en plus du +2 Corruption normal, le dispositif subit un Incident de confinement cohérent. DGT. Les dégâts ci-dessous utilisent l’échelle moderne TUC issue des profils d’armes actuellement joués : couteaux autour de 3-4, armes de mêlée lourdes 7-8, armes de poing 7-11, fusils d’assaut 11-12, précision 12-14 et shotguns lourds jusqu’à 15."}],"lore":"Une relique de Fléau n’est jamais un simple outil exotique : son utilité vient avec une exposition réelle à la Source qui la nourrit, et chaque activation engage le porteur autant que la cible.","compendium":"verite-catalogue-229-equipement-corrompu-et-calamitechnologie-principes","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-fulgur-eb-7', 'Fulgur EB-7', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Épée énergétique à émetteur blindé, lame bleue et âme matérielle, inspirée de l’arme portée par Kirie Gritret."},{"label":"Classification","value":"Lame énergétique · L"},{"label":"Profil","value":"DGT 8 · mêlée · Perforant 3."},{"label":"Activation","value":"Allumer ou éteindre la lame : 1 PA. Éteinte, la poignée et son émetteur restent matériels."},{"label":"Alimentation","value":"Cellule dédiée : 10 scènes de combat avant remplacement ou recharge ; aucun coût en PTV par attaque."},{"label":"Signature","value":"La lame active émet une lumière bleue et un bourdonnement perceptible ; elle compromet une dissimulation dans l’obscurité."},{"label":"Limites","value":"N’accorde ni attaque ni PA supplémentaire ; ne permet pas de parer les tirs et ne touche pas automatiquement les êtres immatériels."},{"label":"Statut éditorial","value":"Modèle et profil validés par l’auteur le 1er octobre 2026, à partir des références visuelles AIDH. Ajout au catalogue postérieur au Livre V V6."}],"lore":"Épée énergétique à émetteur blindé, lame bleue et âme matérielle, inspirée de l’arme portée par Kirie Gritret.","compendium":"verite-catalogue-230-fulgur-eb-7","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('objet', 'objets', 'verite-26-duplex-ar-12', 'Duplex AR-12', NULL, '{"nature":"objets","chapitre":"26","section":"Arsenal AIDH moderne","statut_catalogue":"catalogue","origine":"catalogue","tags":["AIDH"],"proprietes":[{"label":"Description","value":"Fusil compact à deux bouches superposées, inspiré de l’arme portée par Jo Jack Smith. Modes assaut et dispersion."},{"label":"Classification","value":"Fusil d’assaut polyvalent · O"},{"label":"Mode assaut","value":"DGT 16 · portée 70 m · Automatique · Perforant 2."},{"label":"Mode dispersion","value":"DGT 15 · portée 20 m · Perforant 1 · tir unique ; une seule cible, sans zone ni touche automatique."},{"label":"Changement de mode","value":"1 PA. Une attaque utilise un seul mode ; les deux canons ne donnent ni attaque supplémentaire ni double dégât."},{"label":"Réserve","value":"Cartouche-source : environ 1 500 tirs en mode assaut ; un tir de dispersion consomme trois unités de réserve."},{"label":"Verrou AIDH","value":"Signature nanitique, biométrique ou autorisation temporaire."},{"label":"Limites","value":"Plus court de portée qu’un Custodian ; la polyvalence ne supprime ni les couverts ni les tests d’attaque."},{"label":"Statut éditorial","value":"Modèle et profil validés par l’auteur le 1er octobre 2026, à partir des références visuelles AIDH. Ajout au catalogue postérieur au Livre V V6."}],"lore":"Fusil compact à deux bouches superposées, inspiré de l’arme portée par Jo Jack Smith. Modes assaut et dispersion.","compendium":"verite-catalogue-231-duplex-ar-12","mj":false}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
